    /// The worker's ONE build-path decision, every cell of the
    /// mode × records matrix against a hand oracle, plus the clock-shape
    /// derivation each cell implies. The pure seam every branch point in
    /// `graph_run_worker` consults, so the branch points cannot disagree.
    #[test]
    fn the_worker_build_path_resolves_every_mode_and_records_cell() {
        use crate::multiprocess::ExecutionMode;
        // Lockstep: the shipped shape, recording or not — controlled clock,
        // barrier, the (e) ctor.
        for records in [false, true] {
            let path = resolve_worker_build_path(ExecutionMode::Lockstep, records);
            assert_eq!(path, WorkerBuildPath::Lockstep, "records={records}");
            assert!(path.uses_controlled_clock());
        }
        // Free-run, not recording: RealClock (the barrier open is pinned
        // structurally below — it is the `Lockstep` arm's value).
        let live = resolve_worker_build_path(ExecutionMode::FreeRun, false);
        assert_eq!(live, WorkerBuildPath::FreeRunLive);
        assert!(!live.uses_controlled_clock());
        // Free-run, recording: controlled clock (placed at the epoch).
        let rec = resolve_worker_build_path(ExecutionMode::FreeRun, true);
        assert_eq!(rec, WorkerBuildPath::FreeRunRecord);
        assert!(rec.uses_controlled_clock());
    }

    /// The worker's branch points, STRUCTURALLY: the behavioural
    /// halves need a real supervisor spawning real workers (an e2e test;
    /// `mp_worker_box_test` drives the lockstep path only), so what a unit test
    /// in this crate CAN pin is the shape of the worker body:
    ///
    /// * the barrier is opened at EXACTLY ONE site, and that site sits inside
    ///   the `Lockstep` arm of the build-path match (a free-run rank that
    ///   opened the barrier would wait at a generation no sibling arrives at);
    /// * the epoch is ARMED at EXACTLY ONE site (`run_live` places it at its
    ///   wall-clock anchor), AFTER the GO wait (so the ranks' placement
    ///   instants differ by the GO fan-out, never by the sequential-spawn
    ///   skew) and BEFORE `run_live` (an epoch is an origin;
    ///   the primitive refuses a placement after the first step);
    /// * the build-path decision precedes every consumer of it (the clock
    ///   mint, the barrier open, the build, the recording configuration, the
    ///   epoch, the cohort leave).
    ///
    /// Anchored on CODE landmarks over the comment-stripped body (`code_only`),
    /// the same discipline as the wedge-page walks above.
    #[test]
    fn a_free_run_worker_opens_no_barrier_and_places_its_epoch_after_go_before_run_live() {
        let src = code_only(include_str!("graph_cmd.rs"));
        let body = fn_body(&src, "fn graph_run_worker(")
            .expect("the worker fn must still exist — this walk moved with it");

        // ONE decision, ahead of everything it gates.
        let decision = body
            .find("resolve_worker_build_path(")
            .expect("the worker must resolve its build path from the stamped mode");

        // The barrier: one site, inside the Lockstep arm.
        assert_eq!(
            body.matches("open_barrier_with_retry(").count(),
            1,
            "exactly ONE barrier-open site — a second one is a second chance to open it on a \
             free-run rank"
        );
        let open = body.find("open_barrier_with_retry(").unwrap();
        const LOCKSTEP_OPEN: &str =
            "WorkerBuildPath::Lockstep => Some(Arc::new(open_barrier_with_retry(";
        let lockstep_arm = body
            .find(LOCKSTEP_OPEN)
            .expect("the barrier open must be the Lockstep arm's value — never unconditional");
        assert!(
            decision < lockstep_arm,
            "the build-path decision precedes the barrier arm"
        );
        // The ONE open site IS the Lockstep arm's value (a bare
        // `lockstep_arm < open + 1` would be a tautology — the needle contains
        // the open).
        assert_eq!(
            open,
            lockstep_arm + LOCKSTEP_OPEN.len() - "open_barrier_with_retry(".len(),
            "the only barrier-open site is the Lockstep arm's value"
        );
        // …and the arm is not an OR-PATTERN: `FreeRunLive | Lockstep =>` would
        // open the barrier on a free-run rank while still containing the needle.
        assert!(
            !body[..lockstep_arm].trim_end().ends_with('|'),
            "the barrier arm must be `Lockstep` alone, never an or-pattern"
        );

        // The epoch: one ARMING site (placed by `run_live` at its wall-clock
        // anchor — see `place_gating_epoch_at_live_anchor`), after GO, before
        // run_live.
        assert_eq!(
            body.matches("place_gating_epoch_at_live_anchor(").count(),
            1,
            "exactly ONE epoch arming"
        );
        assert_eq!(
            body.matches("place_gating_epoch(").count(),
            0,
            "the worker never places an epoch DIRECTLY — a direct placement bakes its own \
             run_live setup time into the rank's clock domain"
        );
        let epoch = body.find("place_gating_epoch_at_live_anchor(").unwrap();
        let go = body
            .find("wait_for_go(")
            .expect("the worker must still wait for GO");
        let run_live = body
            .find("runtime.run_live(")
            .expect("the worker must still run the live loop");
        assert!(
            go < epoch,
            "the epoch must be ARMED AFTER the GO wait — arming it before bakes the \
             sequential-spawn skew into every rank's clock domain"
        );
        assert!(
            epoch < run_live,
            "the epoch must be ARMED BEFORE run_live — run_live spends the arm at its anchor, \
             and the primitive refuses an arm after the first step"
        );
        // The arming is gated on the FreeRunRecord build path: the LAST
        // build-path mention before the epoch call is that arm's `if let`, and
        // it sits after the GO wait (the guard precedes the call it guards, so
        // the slice to search is `[go, epoch)`, not `[epoch, run_live)`).
        let gate = body[go..epoch]
            .rfind("WorkerBuildPath::")
            .map(|at| go + at)
            .expect("a build-path arm guards the epoch arming");
        assert!(
            body[gate..epoch].starts_with("WorkerBuildPath::FreeRunRecord"),
            "the epoch arming must be gated on the FreeRunRecord build path — the nearest \
             build-path mention before it is: {}",
            &body[gate..(gate + 40).min(body.len())]
        );
        // POLARITY: `if !matches!(..,
        // FreeRunRecord)`, `if build_path != FreeRunRecord` and `if let
        // FreeRunRecord = .. {} else { arm }` all leave the nearest token
        // `FreeRunRecord` while arming on every OTHER path — and the first two
        // put the `!` BEFORE the token, outside a `[gate, epoch)` slice. So the
        // guard is read from the START OF ITS LINE and pinned to the literal
        // positive `if let` (a token-start slice would pass both
        // `!`-before-token shapes; a stray token + unconditional arming would pass
        // the count below).
        let guard_line = body[..gate].rfind('\n').map(|at| at + 1).unwrap_or(0);
        let guard = body[guard_line..epoch].trim();
        assert!(
            guard.starts_with("if let WorkerBuildPath::FreeRunRecord = build_path {"),
            "the arming's guard is the literal positive `if let` on the FreeRunRecord arm, \
             got: {guard}"
        );
        assert!(
            !guard.contains("else") && !guard.contains('!'),
            "the guard between the FreeRunRecord token and the arming carries no negation: \
             {guard}"
        );
        assert_eq!(
            body[go..epoch].matches("WorkerBuildPath::").count(),
            1,
            "exactly ONE build-path token between GO and the arming — the guard itself"
        );
        // The recording-config PAIR is bound to its arm: the nearest build-path
        // token before `configure_recording_runtime_free_run(` is FreeRunRecord
        // (a swapped pair would still pass every count above), and it is NOT
        // the tail of an or-pattern (`Lockstep | FreeRunRecord =>`
        // leaves the nearest token FreeRunRecord while wall-following a
        // lockstep rank).
        let free_cfg = body
            .find("configure_recording_runtime_free_run(")
            .expect("the worker configures the free-run recording runtime");
        let cfg_gate = body[..free_cfg]
            .rfind("WorkerBuildPath::")
            .expect("a build-path arm guards the free-run recording config");
        assert!(
            body[cfg_gate..free_cfg].starts_with("WorkerBuildPath::FreeRunRecord"),
            "the free-run recording config sits under the FreeRunRecord arm, got: {}",
            &body[cfg_gate..(cfg_gate + 40).min(body.len())]
        );
        assert!(
            !body[..cfg_gate].trim_end().ends_with('|'),
            "the FreeRunRecord recording-config arm is not the tail of an or-pattern: {}",
            &body[cfg_gate.saturating_sub(40)..free_cfg]
        );

        // The build-path decision precedes every consumer.
        for consumer in [
            "uses_controlled_clock()",
            "open_barrier_with_retry(",
            "build_live_deterministic_with_manager_and_barrier(",
            "build_live_free_run(",
            "build_live_deterministic_free_run(",
            "configure_recording_runtime_free_run(",
            "configure_recording_runtime_mp(",
            "place_gating_epoch_at_live_anchor(",
            "leave_barrier_cohort(",
        ] {
            let at = body
                .find(consumer)
                .unwrap_or_else(|| panic!("the worker body must still contain `{consumer}`"));
            assert!(
                decision < at,
                "`{consumer}` must come AFTER the build-path decision it branches on"
            );
        }

        // ANTI-TAUTOLOGY: the stripped view really holds this function's code.
        assert!(
            body.contains("MappedWedgePage::open_unowned"),
            "the stripper ate the worker body"
        );
    }

    /// The supervisor CREATES every credit word, and
    /// checks the edge list for duplicates — BEFORE it spawns any worker.
    ///
    /// The ordering is the whole safety property and it is invisible at either
    /// site. A create that failed AFTER a spawn would leave live workers
    /// blocking on `open_unowned` for a word that will never appear (they
    /// retry to a ten-second deadline each, sequentially) while the supervisor
    /// unwound; and a duplicate discovered after the first `create_owned` would
    /// already have had owner #1's `Drop` unlink owner #2's live page. Both are
    /// prevented by position, not by a check, so position is what is pinned.
    ///
    /// STRUCTURAL over the comment- and literal-stripped body, because there is
    /// no seam to inject a `create_owned` failure at: the alternative is a
    /// hostile `/dev/shm` state the test would have to build and then race.
    #[test]
    fn the_supervisor_creates_every_credit_word_before_it_spawns_any_worker() {
        let src = code_only(include_str!("graph_cmd.rs"));
        let body = fn_body(&src, "fn graph_run_supervisor(").expect("the supervisor entry point");
        // Markers are CODE, never string literals: `code_only` blanks literals,
        // so `"run-worker"` would be invisible to this walk. `graph_run_worker`
        // is defined ABOVE the supervisor, so each first hit below is the
        // supervisor's own.
        let dedupe = body
            .find("check_credit_edges_unique(")
            .expect("the supervisor checks its edge list for duplicates");
        let create = body
            .find("MappedCredit::create_owned(")
            .expect("the supervisor creates the credit words");
        let spawn = body
            .find("spawn_order(&plan)")
            .expect("the supervisor spawns workers in plan order");
        assert!(
            dedupe < create,
            "the duplicate check must precede the FIRST create: owner #1's drop would otherwise \
             already have unlinked owner #2's live page"
        );
        assert!(
            create < spawn,
            "every credit word must exist BEFORE any worker is spawned — a worker that opens \
             one that never arrives rides its full retry deadline, per edge, in sequence"
        );
        // ANTI-TAUTOLOGY: the stripped view really holds this function's code,
        // and the two markers above are not being found in prose.
        assert!(
            body.contains("credit_create_failure_message("),
            "the stripper ate the supervisor body"
        );
    }

    /// The execution-mode environment is read
    /// EXACTLY ONCE, inside `graph_run` — the supervisor and the worker receive
    /// the resolved value and never re-derive it (a second read is the drift
    /// the "one decision" design forbids; the worker already reads other env at
    /// its own sites, so this is the natural regression). Structural, over the
    /// comment-stripped source.
    #[test]
    fn the_execution_mode_env_is_read_exactly_once_and_only_in_graph_run() {
        let src = code_only(include_str!("graph_cmd.rs"));
        assert_eq!(
            src.matches("(EXECUTION_MODE_ENV)").count(),
            1,
            "exactly one read of the execution-mode env in this file"
        );
        let body = fn_body(&src, "pub fn graph_run(").expect("graph_run must still exist");
        assert!(
            body.contains("var_os(EXECUTION_MODE_ENV)"),
            "the one read lives in `graph_run`, via `var_os` (a non-UTF-8 value is garbage, \
             never \"unset\")"
        );
        for other in ["fn graph_run_supervisor(", "fn graph_run_worker("] {
            let b = fn_body(&src, other).expect("the fn must still exist");
            assert!(
                !b.contains("EXECUTION_MODE_ENV"),
                "{other} must receive the resolved mode, never re-read the env"
            );
        }
    }

    /// The checked rank → ring-header-rank conversion.
    /// In-range ranks pass through; `u32::MAX` (the departure-ring
    /// sentinel reservation) and above are rejected LOUDLY, never silently
    /// truncated — the error names the sentinel reservation.
    #[cfg(unix)]
    #[test]
    fn worker_ring_rank_bounds() {
        // Happy path: real ranks are tiny group indices.
        assert_eq!(worker_ring_rank(0).expect("rank 0"), 0);
        assert_eq!(worker_ring_rank(7).expect("rank 7"), 7);
        // Boundary: the largest VALID rank is TRACE_RANK_MASK - 1.
        assert_eq!(
            worker_ring_rank(cerulion_core::trace_ring::TRACE_RANK_MASK as usize - 1)
                .expect("one below the mask is valid"),
            cerulion_core::trace_ring::TRACE_RANK_MASK - 1
        );
        // u32::MAX is reserved (departure sentinel) — rejected, loudly.
        let err = worker_ring_rank(u32::MAX as usize).expect_err("u32::MAX must be rejected");
        let msg = err.to_string();
        assert!(
            msg.contains("departure"),
            "rejection must name the departure-sentinel reservation, got: {msg}"
        );
        // TRACE_RANK_MASK is reserved TOO. A worker there marking a
        // discarded FIRE stamps `mask | TRACE_DISCARD_BIT` == u32::MAX, which
        // `is_departure_boundary` compares UNMASKED and reads as a fault
        // boundary — so `bag play --resim` would refuse a healthy bag and a
        // Flashback capture would report `FaultReplay` for a run that lost
        // nobody. Asserted as ARITHMETIC, not as a literal, so the two
        // constants cannot drift apart from this claim.
        assert_eq!(
            cerulion_core::trace_ring::TRACE_RANK_MASK
                | cerulion_core::trace_ring::TRACE_DISCARD_BIT,
            cerulion_core::trace_ring::DEPARTURE_RING_RANK,
            "the reservation below only makes sense while this aliasing holds"
        );
        let err = worker_ring_rank(cerulion_core::trace_ring::TRACE_RANK_MASK as usize)
            .expect_err("TRACE_RANK_MASK must be rejected — it aliases the sentinel when marked");
        let msg = err.to_string();
        assert!(
            msg.contains("departure-ring sentinel") && msg.contains("discard-marked"),
            "the rejection must say WHY this particular rank is reserved, got: {msg}"
        );
        // Above u32::MAX (unrepresentable) — rejected on 64-bit targets.
        #[cfg(target_pointer_width = "64")]
        {
            worker_ring_rank(u32::MAX as usize + 1)
                .expect_err("a rank above u32::MAX must be rejected, never truncated");
        }
    }

