    // =======================================================================
    // The collision-disambiguated stem
    // moves ALL SIX artifact names together (bag + the scratch quintet —
    // the schema catalog is the fifth scratch file).
    // =======================================================================

    #[cfg(unix)]
    #[test]
    fn recording_paths_collision_suffixes_all_six_names() {
        let tmp = tempfile::tempdir().unwrap();
        let now = Duration::from_millis(1_783_092_278_948); // stamp 20260703T152438Z
                                                            // No collision: bare-stem names.
        let clean = resolve_recording_paths(tmp.path(), "demo", now);
        assert_eq!(
            clean.out,
            tmp.path().join("demo_20260703T152438Z.mcap"),
            "bare stem when no incumbent bag exists"
        );
        assert_eq!(clean.ready, tmp.path().join(".demo_20260703T152438Z.ready"));

        // Collision: pre-create the bare-stem bag → ALL SIX names get the
        // millis suffix (no overwrite; no scratch race with the incumbent).
        std::fs::write(&clean.out, b"incumbent").unwrap();
        let bumped = resolve_recording_paths(tmp.path(), "demo", now);
        let stem = "demo_20260703T152438Z_1783092278948";
        assert_eq!(bumped.out, tmp.path().join(format!("{stem}.mcap")));
        assert_eq!(bumped.ready, tmp.path().join(format!(".{stem}.ready")));
        assert_eq!(
            bumped.topics_json,
            tmp.path().join(format!(".{stem}.topics.json"))
        );
        assert_eq!(
            bumped.env_json,
            tmp.path().join(format!(".{stem}.env.json"))
        );
        assert_eq!(
            bumped.recorder_json,
            tmp.path().join(format!(".{stem}.recorder.json"))
        );
        assert_eq!(
            bumped.schema_catalog,
            tmp.path().join(format!(".{stem}.schemas.json"))
        );
        assert_eq!(
            std::fs::read(&clean.out).unwrap(),
            b"incumbent",
            "the incumbent bag is never overwritten"
        );
    }

    // =======================================================================
    // `graph run --record` hands bagd this machine's schema catalog.
    //
    // bagd is a SUBPROCESS on this path, so the catalog can only cross as a
    // FILE. These pin the CLI half — that the file is written, that it carries
    // the workspace's custom-type text VERBATIM, and that it is scratch (never
    // left behind). The bagd half (reading the flag) is
    // `cerulion_bagd::schema_catalog_arg_tests`; the closed loop over the
    // real binary is `crates/cerulion_cli/tests/graph_record_e2e_test.rs`.
    // =======================================================================

    /// The `.msg` text a temp workspace ships — the byte oracle every assertion
    /// below compares against (never a self-compare against what was read back).
    #[cfg(unix)]
    const PROBE_MSG: &str = "# a type no desk has compiled\nuint8 mode\nfloat64 charge\n";

    #[cfg(unix)]
    fn workspace(root: &Path) {
        std::fs::create_dir_all(root.join("schemas/msgs/msg")).unwrap();
        std::fs::create_dir_all(root.join("graphs")).unwrap();
        std::fs::write(root.join("schemas/msgs/msg/Probe.msg"), PROBE_MSG).unwrap();
    }

    /// The record-time coverage report, driven through the
    /// PRODUCTION seam — `prepare_recording_inputs`, not the reporter directly.
    ///
    /// That distinction is not stylistic: arms that call
    /// `report_record_schema_coverage` itself survive deleting its CALL SITE
    /// (the tests keep the function alive, so even `dead_code = deny`
    /// stays quiet). That pins the reporter; the WIRING — the only thing a
    /// recording actually depends on — it does not.
    ///
    /// This is the arm bagd's own warn cannot reach on this path: it filters on
    /// the ATTACH-mode `"unknown"` placeholder, and `graph run --record` hands
    /// bagd EXACT taps named from the graph.
    #[cfg(unix)]
    #[test]
    #[tracing_test::traced_test]
    fn an_unresolvable_recorded_hash_is_named_at_record_time_not_discovered_at_playback() {
        let ws = tempfile::tempdir().unwrap();
        workspace(ws.path());
        let rec = ws.path().join("recordings");

        let _inputs = prepare_recording_inputs(RecordingInputSpec {
            embed_config: &recorded_topics_config(),
            record_dir: &rec,
            workspace_root: ws.path(),
            graphs_dir: &ws.path().join("graphs"),
            graph_name: "demo",
            // The effective config the bag would embed. These arms pin
            // the schema-coverage report, which does not read it — the
            // embed itself is pinned by the effective-config arms below.
            // The DRIFT shape: a compiled node's AUTHORITATIVE hash that no
            // current workspace text explains, beside a resolvable built-in.
            recorded: &[
                recorded_topic("/cmd", VECTOR3_WIRE_HASH),
                recorded_topic("/drifted", 0xDEAD_BEEF_DEAD_BEEF),
            ],
            record_env: RecordEnvMode::None,
            coordination: crate::replay_engine::CoordinationMode::Lockstep,
        })
        .expect("prepare");

        // The LEVEL is part of the predicate, not decoration:
        // `tracing-test` captures at "trace", so a `warn!`→`debug!` demotion
        // leaves a message-only assertion green while the line vanishes from a
        // default `graph run` (`cerulion=info`).
        logs_assert(|lines: &[&str]| {
            let warns = count_at(lines, "WARN", "resolve against NOTHING this machine knows");
            if warns != 1 {
                return Err(format!(
                    "expected exactly 1 WARN naming the unresolvable hashes (a demoted line \
                     never reaches a default `graph run`), got {warns}"
                ));
            }
            Ok(())
        });
        assert!(
            logs_contain("/drifted"),
            "the warn must NAME the offending topic: bagd's own warn cannot, since by then \
             the graph's schema name has replaced the placeholder it filters on"
        );
        assert!(
            !logs_contain("/cmd\""),
            "a resolvable topic must not be named as a problem"
        );
    }

    #[cfg(unix)]
    const LEVELS: [&str; 5] = ["TRACE", "DEBUG", "INFO", "WARN", "ERROR"];

    /// The LEVEL token of one captured line, or `None` if its header carries
    /// none — the whole-token form from
    /// `crates/rmw_cerulion/tests/rmw_publish_reject_test.rs::line_level`, not the
    /// older `line.contains(level)` substring test.
    ///
    /// `tracing-test` renders `<timestamp> <LEVEL> <span>: <target>: <message>
    /// <fields>`, and the SPAN is the test function's own name. A substring
    /// match therefore counts a line whose span name, target or any field VALUE
    /// happens to contain the token — so a rename or an uppercase field value
    /// could silently invert an "exactly N" oracle in either direction. Not
    /// invertible for these two arms TODAY (the span names are lowercase, the
    /// target is `cerulion_cli_engine::graph_cmd`, and the fields are topic
    /// paths and counts), which is exactly why it is worth fixing before it is:
    /// the repo already burned itself on this class once.
    ///
    /// Reading whole whitespace tokens out of the HEADER (everything before the
    /// first `": "`) means a message body never votes. An unparseable header
    /// yields `None` and matches no level — safe for the two COUNT oracles here,
    /// which fail rather than pass on a zero.
    #[cfg(unix)]
    fn line_level(line: &str) -> Option<&'static str> {
        let header = line.split(": ").next().unwrap_or(line);
        header
            .split_whitespace()
            .find_map(|token| LEVELS.into_iter().find(|level| *level == token))
    }

    /// Count captured lines carrying BOTH the level token and the marker.
    #[cfg(unix)]
    fn count_at(lines: &[&str], level: &str, marker: &str) -> usize {
        lines
            .iter()
            .filter(|l| line_level(l) == Some(level) && l.contains(marker))
            .count()
    }

    /// ANTI-TAUTOLOGY for the arm above: a fully-resolved recording reports the
    /// healthy line and NOT the warning, so the warn is earned by the
    /// unresolvable hash rather than fired unconditionally. A BUILT-IN binding
    /// (a name, no doc) counts as resolved — every Cerulion binary compiles its
    /// text in, so shipping no doc for it costs a reader nothing.
    #[cfg(unix)]
    #[test]
    #[tracing_test::traced_test]
    fn a_fully_resolved_recording_reports_coverage_and_no_warning() {
        let ws = tempfile::tempdir().unwrap();
        workspace(ws.path());
        let rec = ws.path().join("recordings");

        let _inputs = prepare_recording_inputs(RecordingInputSpec {
            embed_config: &recorded_topics_config(),
            record_dir: &rec,
            workspace_root: ws.path(),
            graphs_dir: &ws.path().join("graphs"),
            graph_name: "demo",
            // The effective config the bag would embed. These arms pin
            // the schema-coverage report, which does not read it — the
            // embed itself is pinned by the effective-config arms below.
            recorded: &[recorded_topic("/cmd", VECTOR3_WIRE_HASH)],
            record_env: RecordEnvMode::None,
            coordination: crate::replay_engine::CoordinationMode::Lockstep,
        })
        .expect("prepare");

        logs_assert(|lines: &[&str]| {
            let infos = count_at(
                lines,
                "INFO",
                "every recorded topic's wire schema hash resolves",
            );
            if infos != 1 {
                return Err(format!(
                    "expected exactly 1 INFO on the healthy path, at a level a default \
                     `graph run` prints, got {infos}"
                ));
            }
            // `docs` must count what the BAG gets, not this machine's corpus.
            // The fixture workspace holds ONE custom type (`msgs/Probe`)
            // and records NONE of it — the recorded topic is a built-in — so the
            // pruned closure is EMPTY while the unpruned corpus is 1. That is the
            // discriminator: reporting `catalog.docs.len()` prints `docs=1` for a
            // bag that carries no definitions at all.
            let pruned_lines = count_at(lines, "INFO", "docs=0");
            if pruned_lines != 1 {
                return Err(format!(
                    "the info's `docs` must be the PRUNED count the bag really gets \
                     (expected `docs=0` here — the workspace's one custom type is not \
                     recorded), got {pruned_lines} matching lines"
                ));
            }
            Ok(())
        });
        assert!(
            !logs_contain("resolve against NOTHING this machine knows"),
            "a fully-resolved recording must not warn"
        );
    }

    /// The built-in `geometry_msgs/Vector3` wire hash — resolvable through the
    /// catalog's built-in BINDINGS with no workspace text at all.
    #[cfg(unix)]
    const VECTOR3_WIRE_HASH: u64 = {
        use cerulion_core::ShmMessage as _;
        native_ros2_messages::geometry_msgs::Vector3::SCHEMA_HASH
    };

    #[cfg(unix)]
    fn recorded_topic(topic: &str, schema_hash: u64) -> cerulion_bagd::RecordedTopic {
        cerulion_bagd::RecordedTopic {
            format: cerulion_bagd::RECORDED_TOPIC_FORMAT,
            topic: topic.to_string(),
            // Irrelevant here: the coverage check keys off the wire HASH, which
            // is what a reader resolves by. The name only labels the channel.
            schema_name: "irrelevant/Here".to_string(),
            schema_hash,
            wire_fixed_size: 0,
            multi_publisher: false,
        }
    }

    #[cfg(unix)]
    #[test]
    fn recording_inputs_write_the_workspace_schema_catalog_verbatim() {
        let ws = tempfile::tempdir().unwrap();
        workspace(ws.path());
        std::fs::write(
            ws.path().join("graphs/demo.yaml"),
            "name: demo\nnodes: []\n",
        )
        .unwrap();
        let rec = ws.path().join("recordings");

        let inputs = prepare_recording_inputs(RecordingInputSpec {
            embed_config: &recorded_topics_config(),
            record_dir: &rec,
            workspace_root: ws.path(),
            graphs_dir: &ws.path().join("graphs"),
            graph_name: "demo",
            // The effective config the bag would embed. These arms pin
            // the schema-coverage report, which does not read it — the
            // embed itself is pinned by the effective-config arms below.
            recorded: &[],
            record_env: RecordEnvMode::None,
            coordination: crate::replay_engine::CoordinationMode::Lockstep,
        })
        .expect("prepare");

        let path = inputs
            .schema_catalog
            .clone()
            .expect("a workspace holding a custom type must hand bagd a catalog");
        assert_eq!(
            path, inputs.paths.schema_catalog,
            "the argument path must be the derived scratch path"
        );
        let catalog =
            cerulion_bag::BagSchemaCatalog::decode(&std::fs::read(&path).unwrap()).expect("decode");
        let probe = catalog
            .docs
            .iter()
            .find(|d| d.qualified == "msgs/Probe")
            .expect("the workspace's custom type must be in the catalog");
        // The whole point of the feature: the TEXT crosses, byte for byte.
        assert_eq!(probe.text, PROBE_MSG);
        // …and so does the CUSTOM type's hash BINDING, which is what makes the
        // text reachable: `closure_for_hashes` resolves a
        // recorded hash to a NAME through `hashes`, then looks the doc up by
        // that name. A catalog carrying `msgs/Probe`'s text with no
        // binding for its hash ships a doc no reader can ever reach — and every
        // OTHER arm here resolves through the BUILT-IN tier (the fixture
        // cdylibs publish `geometry_msgs/Vector3`), so nothing else here can see
        // that. Dropping `hashes.extend(custom_hashes)` from
        // `build_record_schema_catalog` fails exactly this assertion.
        assert!(
            catalog.hashes.iter().any(|h| h.qualified == "msgs/Probe"),
            "a custom type's hash→name binding must cross the file hop, or its text \
             is unreachable: {:?}",
            catalog
                .hashes
                .iter()
                .map(|h| &h.qualified)
                .collect::<Vec<_>>()
        );
        // Built-ins contribute NAME bindings (never text), so a bag can name a
        // channel even where it ships no definition.
        assert!(
            catalog
                .hashes
                .iter()
                .any(|h| h.qualified == "geometry_msgs/Vector3"),
            "built-in hash bindings ride along so channels resolve by name"
        );
        assert!(
            !catalog
                .docs
                .iter()
                .any(|d| d.qualified.starts_with("geometry_msgs/")),
            "built-in TEXT is dead weight — every Cerulion binary compiles it in"
        );

        // Scratch, not a deliverable: the RAII guard removes it on every exit.
        drop(inputs);
        assert!(
            !path.exists(),
            "the catalog file is scratch and must not survive the run"
        );
    }

    /// The ANTI-TAUTOLOGY half of the test above: a workspace holding no custom
    /// types ships NO schema text, proving the `msgs/Probe` doc there is
    /// earned by the workspace's content rather than produced unconditionally.
    /// It still ships the built-in NAME bindings — the two tiers are deliberately
    /// split (see `bag_cmd::build_record_schema_catalog`).
    #[cfg(unix)]
    #[test]
    fn a_workspace_with_no_custom_types_ships_name_bindings_but_no_text() {
        let ws = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(ws.path().join("graphs")).unwrap();
        std::fs::write(
            ws.path().join("graphs/demo.yaml"),
            "name: demo\nnodes: []\n",
        )
        .unwrap();
        let rec = ws.path().join("recordings");

        // `build_record_schema_catalog` always contributes the BUILT-IN hash
        // bindings, so a real workspace can never reach the `None` arm — it is
        // reachable only if the built-in corpus itself is empty. Assert what a
        // schema-less workspace really produces: bindings, and no text.
        let inputs = prepare_recording_inputs(RecordingInputSpec {
            embed_config: &recorded_topics_config(),
            record_dir: &rec,
            workspace_root: ws.path(),
            graphs_dir: &ws.path().join("graphs"),
            graph_name: "demo",
            // The effective config the bag would embed. These arms pin
            // the schema-coverage report, which does not read it — the
            // embed itself is pinned by the effective-config arms below.
            recorded: &[],
            record_env: RecordEnvMode::None,
            coordination: crate::replay_engine::CoordinationMode::Lockstep,
        })
        .expect("prepare");
        let path = inputs.schema_catalog.clone().expect("built-in bindings");
        let catalog =
            cerulion_bag::BagSchemaCatalog::decode(&std::fs::read(&path).unwrap()).expect("decode");
        assert!(
            catalog.docs.is_empty(),
            "a workspace with no custom types ships no schema TEXT: {:?}",
            catalog
                .docs
                .iter()
                .map(|d| &d.qualified)
                .collect::<Vec<_>>()
        );
        assert!(
            !catalog.hashes.is_empty(),
            "built-in name bindings still ride"
        );
    }

    // ---------------------------------------------------------------
    // The bag's `graph.yaml` attachment is the EFFECTIVE config
    // ---------------------------------------------------------------

    /// The effective config with a DERIVED partition installed and NO `prefix:`
    /// — i.e. exactly the two ways `graphs/<file>.yaml` and the config a run
    /// executes diverge (the auto-partition no-TTY floor; the run-time prefix fill).
    #[cfg(unix)]
    fn effective_config() -> GraphConfig {
        let mut config = recorded_topics_config();
        config.prefix = "resolved_host".to_string();
        config.process_groups = [
            ("p0".to_string(), vec!["cam".to_string()]),
            ("p1".to_string(), vec!["det".to_string()]),
        ]
        .into_iter()
        .collect();
        config
    }

    /// Read back what `prepare_recording_inputs` will hand bagd as the
    /// `graph.yaml` attachment.
    #[cfg(unix)]
    fn embedded_graph_yaml(config: &GraphConfig) -> (tempfile::TempDir, String) {
        let ws = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(ws.path().join("graphs")).unwrap();
        let inputs = prepare_recording_inputs(RecordingInputSpec {
            embed_config: config,
            record_dir: &ws.path().join("recordings"),
            workspace_root: ws.path(),
            graphs_dir: &ws.path().join("graphs"),
            graph_name: "demo",
            recorded: &[recorded_topic("/cmd", VECTOR3_WIRE_HASH)],
            record_env: RecordEnvMode::None,
            coordination: crate::replay_engine::CoordinationMode::Lockstep,
        })
        .expect("prepare");
        let text = std::fs::read_to_string(&inputs.graph_yaml)
            .expect("the rendered graph.yaml scratch file must exist");
        // Keep `inputs` (and its ScratchGuard) alive until after the read; hand
        // the tempdir back so the caller's assertions outlive it too.
        drop(inputs);
        (ws, text)
    }

    /// THE pin: what a run EXECUTES is what the bag embeds.
    ///
    /// `graphs/<file>.yaml` is deliberately NOT written on the no-TTY
    /// consent floor, so on the headless/robot shape the on-disk file carries no
    /// `process_groups:` while the run goes multi-process and the recording stamps one
    /// trace manifest per rank. Reading the file for the attachment produced a
    /// bag that contradicted itself.
    ///
    /// The prefix half rides the same assertion for the same reason: `graph_read`
    /// leaves an absent `prefix:` absent, `graph_run` resolves it, and
    /// `resolve_recorded_topics` names every recorded channel under the RESOLVED
    /// one — while `replay_cmd` re-fills a missing prefix from the REPLAY host
    /// and `classify_topics` resolves topic names under that. A prefix-less
    /// embed is therefore a cross-machine `BagGraphMismatch` waiting to happen.
    ///
    /// NOTE the negative half: NO path under the recording dir may be the user's
    /// graph file, and the workspace's `graphs/` dir is not even populated here —
    /// so this arm would fail outright on any implementation that read it.
    #[cfg(unix)]
    #[test]
    fn the_bag_embeds_the_effective_config_not_the_on_disk_graph_file() {
        let config = effective_config();
        let (_ws, yaml) = embedded_graph_yaml(&config);

        // Hand oracle: re-parsing the embed yields the EXECUTED partition.
        let parsed = cerulion_core::graph::parse_graph_raw(&yaml).expect("the embed must parse");
        assert_eq!(
            parsed.process_groups, config.process_groups,
            "the embedded graph must carry the process_groups the run EXECUTED — a bag whose \
             graph says single-process while its trace carries N ranks is the self-contradicting-bag defect.\n\
             embedded:\n{yaml}"
        );
        assert_eq!(
            parsed.prefix, "resolved_host",
            "the embedded graph must carry the RESOLVED prefix: recorded channel names are \
             derived from it, and replay re-derives topic names from whatever the embed says \
             (filling an absent prefix from the REPLAY host).\nembedded:\n{yaml}"
        );
        // The whole config, not just the two fields the arms above name.
        assert_eq!(
            parsed.name, config.name,
            "every other field rides too:\n{yaml}"
        );
        assert_eq!(parsed.nodes.len(), config.nodes.len(), "node list rides");
        assert_eq!(
            parsed.multi_publisher_topics, config.multi_publisher_topics,
            "multi_publisher_topics rides"
        );
    }

    /// The embed must survive the exact gauntlet `cerulion replay` runs it
    /// through — `parse_graph` THEN `validate_graph` — or the embed would trade a
    /// self-contradicting bag for an unreplayable one (exit 2, "corrupt or
    /// hand-edited"): `validate_graph` calls `partition::validate_process_groups`,
    /// which hard-errors on an empty group, a node in two groups, or ANY declared
    /// node left unassigned. A partition is only inert for replay while it is
    /// well-formed and node-COMPLETE, so the property is asserted rather than
    /// assumed.
    ///
    /// The anti-tautology half is in the same body: a partition that omits a
    /// declared node — the shape a partial derivation would produce — must be
    /// REFUSED by that same validator, so this arm cannot pass against a
    /// validator that accepts everything.
    #[cfg(unix)]
    #[test]
    fn the_embedded_graph_passes_the_gauntlet_replay_puts_it_through() {
        let mut config = effective_config();
        // Node-COMPLETE: every declared node assigned to exactly one group.
        config.process_groups = [(
            "p0".to_string(),
            config
                .nodes
                .iter()
                .map(|n| n.id.clone())
                .collect::<Vec<_>>(),
        )]
        .into_iter()
        .collect();
        let (_ws, yaml) = embedded_graph_yaml(&config);

        let parsed = cerulion_core::graph::parse_graph(&yaml)
            .expect("replay parses the embed with parse_graph");
        cerulion_core::graph::validate_graph(&parsed).unwrap_or_else(|e| {
            panic!(
                "the embedded graph must pass the SAME validation `cerulion replay` runs, or \
                 every recorded multi-process bag becomes exit-2 unreplayable: {e}\n{yaml}"
            )
        });

        // Anti-tautology: the validator this arm leans on really does refuse a
        // partition that leaves a declared node unassigned.
        let mut partial = parsed.clone();
        partial.process_groups = [("p0".to_string(), vec![config.nodes[0].id.clone()])]
            .into_iter()
            .collect();
        assert!(
            cerulion_core::graph::validate_graph(&partial).is_err(),
            "control: a partition omitting a declared node must be REFUSED — otherwise the \
             assertion above proves nothing about well-formedness"
        );
    }

    /// The render must ROUND-TRIP through the parser replay uses. The embed is
    /// serde-normalized (comments dropped, struct key order, empty blocks
    /// omitted), which is lossless only if every field survives the trip — so
    /// that is measured, not asserted in prose.
    #[cfg(unix)]
    #[test]
    fn the_effective_graph_yaml_round_trips_through_the_replay_parser() {
        let config = effective_config();
        let rendered = render_effective_graph_yaml(&config).expect("render");
        let back = cerulion_core::graph::parse_graph_raw(&rendered).expect("re-parse");

        assert_eq!(back.name, config.name);
        assert_eq!(back.prefix, config.prefix);
        assert_eq!(back.process_groups, config.process_groups);
        assert_eq!(back.process_group_order, config.process_group_order);
        assert_eq!(back.multi_publisher_topics, config.multi_publisher_topics);
        assert_eq!(back.nodes.len(), config.nodes.len());
        for (a, b) in back.nodes.iter().zip(config.nodes.iter()) {
            assert_eq!(a.id, b.id);
            assert_eq!(a.node_type, b.node_type);
            assert_eq!(
                a.inputs
                    .iter()
                    .map(|i| (&i.name, &i.source))
                    .collect::<Vec<_>>(),
                b.inputs
                    .iter()
                    .map(|i| (&i.name, &i.source))
                    .collect::<Vec<_>>(),
                "input wiring survives the round trip"
            );
            assert_eq!(
                a.outputs
                    .iter()
                    .map(|o| (&o.name, &o.schema, &o.topic))
                    .collect::<Vec<_>>(),
                b.outputs
                    .iter()
                    .map(|o| (&o.name, &o.schema, &o.topic))
                    .collect::<Vec<_>>(),
                "output declarations — including `topic:` overrides, which name \
                 recorded channels — survive the round trip"
            );
        }

        // A SECOND trip is byte-identical: the rendering is a fixed point, so a
        // bag's graph attachment does not drift if it is ever re-rendered.
        assert_eq!(
            render_effective_graph_yaml(&back).expect("render again"),
            rendered,
            "the render must be idempotent"
        );
    }

    /// The rendered attachment is SCRATCH: it must be cleaned up like every other
    /// bagd input, never left beside the bag as a stray artifact.
    #[cfg(unix)]
    #[test]
    fn the_rendered_graph_yaml_is_scratch_and_is_swept_on_drop() {
        let ws = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(ws.path().join("graphs")).unwrap();
        let rec = ws.path().join("recordings");
        let inputs = prepare_recording_inputs(RecordingInputSpec {
            embed_config: &effective_config(),
            record_dir: &rec,
            workspace_root: ws.path(),
            graphs_dir: &ws.path().join("graphs"),
            graph_name: "demo",
            recorded: &[recorded_topic("/cmd", VECTOR3_WIRE_HASH)],
            record_env: RecordEnvMode::None,
            coordination: crate::replay_engine::CoordinationMode::Lockstep,
        })
        .expect("prepare");
        let path = inputs.graph_yaml.clone();
        assert!(path.exists(), "the rendered attachment exists while armed");
        drop(inputs);
        assert!(
            !path.exists(),
            "the rendered graph.yaml must be swept by the scratch guard — a recording dir must \
             not accumulate stray graph files beside its bags"
        );
    }

    /// A workspace `.msg` that SHADOWS a built-in re-derives to the SAME wire hash
    /// the generated type stamps — asserted on the CUSTOM half of the builder's
    /// output, which is the only place that claim is observable.
    ///
    /// The obvious form of this test does NOT test it: asking
    /// the merged catalog `name_for_hash(Vector3::SCHEMA_HASH)` is answered by
    /// `builtin_hash_bindings()`, which supplies that pair unconditionally — so
    /// it passes no matter what the shadow's `.msg` parses to, and cannot fail
    /// from the recipe drift its own message names. `normalize()` then dedups
    /// `hashes` by `schema_hash`, so once the two agree they collapse into one
    /// entry and the merged list can no longer tell them apart either. Driving
    /// `build_schema_docs` directly is what isolates the shadow's own hash.
    ///
    /// **What the e2e text arms actually rely on is NAME resolution, not this
    /// coincidence.** `closure_for_hashes` maps a recorded hash to a NAME (via
    /// any binding, built-in included) and then looks the doc up BY NAME, so a
    /// workspace doc named `geometry_msgs/Vector3` is shipped for a recorded
    /// Vector3 frame whatever it hashes to. This arm is therefore about the
    /// SHADOW shape being coherent — a real shipping shape
    /// (`SchemaStore::builtin_shadows`; such text is recorded by design)
    /// where a divergent hash would mean the bag ships text that explains a
    /// different type than the one on the wire.
    #[cfg(unix)]
    #[test]
    fn a_workspace_msg_shadowing_a_builtin_re_derives_the_builtins_own_wire_hash() {
        use cerulion_core::ShmMessage as _;

        let ws = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(ws.path().join("schemas/geometry_msgs/msg")).unwrap();
        std::fs::write(
            ws.path().join("schemas/geometry_msgs/msg/Vector3.msg"),
            "float64 x\nfloat64 y\nfloat64 z\n",
        )
        .unwrap();

        // The CUSTOM half only — `build_record_schema_catalog` merges the
        // built-in bindings in, which is exactly what would mask the answer.
        let (docs, custom_hashes) =
            crate::schema_serve::build_schema_docs(&ws.path().join("schemas"), None);
        assert!(
            docs.iter().any(|d| d.qualified == "geometry_msgs/Vector3"),
            "the shadow's TEXT is recorded (it is what explains its hash)"
        );
        let shadow = custom_hashes
            .iter()
            .find(|h| h.qualified == "geometry_msgs/Vector3")
            .expect("the shadow must contribute its OWN binding");
        assert_eq!(
            shadow.schema_hash,
            native_ros2_messages::geometry_msgs::Vector3::SCHEMA_HASH,
            "the shadow's re-derived hash must equal the generated type's, or the bag \
             ships text describing a different type than the frames carry"
        );
    }

    /// `render_recorder_json` carries EXACTLY
    /// the five flat fields (a sacred user-facing format — a speculative SIXTH
    /// field fails the count pin), with `arch`/`os` from the compile-time consts,
    /// `recorded_at_ns` equal to the filename-stamp `now` (no second clock), and
    /// `trace_format` = the INTENTIONAL scheduler-trace format version this binary
    /// writes. `trace_format` is the fifth field (the discard-bit-
    /// aware v2) so replay refuses a bag from a newer binary instead of mis-
    /// decoding the discard bit — the exact-count assert stays (no-speculative-
    /// extras spirit is preserved; the count moves 4 → 5 for one intentional add).
    #[cfg(unix)]
    #[test]
    fn recorder_json_carries_exactly_the_six_host_fields() {
        use crate::replay_engine::CoordinationMode;
        let now = Duration::from_nanos(1_783_092_278_948_123_456);
        let v: serde_json::Value =
            serde_json::from_slice(&render_recorder_json(now, CoordinationMode::Lockstep))
                .expect("valid JSON");
        let obj = v.as_object().expect("flat object");
        assert_eq!(
            obj.len(),
            6,
            "exactly six fields (arch/os/cerulion_version/recorded_at_ns + the \
             trace_format + the coordination stamp) — no speculative extras"
        );
        assert_eq!(v["arch"], std::env::consts::ARCH);
        assert_eq!(v["os"], std::env::consts::OS);
        assert_eq!(v["cerulion_version"], env!("CARGO_PKG_VERSION"));
        assert_eq!(v["recorded_at_ns"], 1_783_092_278_948_123_456u64);
        // The sixth field: the coordination contract this run
        // executed under, stamped EXPLICITLY on every bag so an ABSENT key means
        // exactly "an older bag". Pinned as the WIRE SPELLING (a snake_case
        // literal), not against the enum, so a rename is a deliberate change.
        assert_eq!(v["coordination"], "lockstep");
        // The scheduler-trace FORMAT version. It is
        // the PER-BAG stamp, resolved through `stamp_trace_format` (the source
        // of that decision) rather than restated here. Every bag
        // this binary writes carries READ-SITE ROLES, so the stamp is 5 — a
        // lockstep bag does NOT stamp 3, and the stamp is not
        // compared against the read gate here (the two
        // remain separate decisions; see
        // `replay_engine::write_stamp_and_read_gate_stay_two_decisions`).
        assert_eq!(
            v["trace_format"],
            crate::replay_engine::stamp_trace_format(
                CoordinationMode::Lockstep,
                crate::replay_engine::recorder_stream_needs_v4(),
                crate::replay_engine::recorder_stamps_read_site_roles(),
                cerulion_core::read_outcome::fold_enabled()
            )
        );
        assert_eq!(
            v["trace_format"], 6,
            "C3: every bag this binary writes carries read-site roles AND \
             folds runs, and folding is the stronger claim — a reader below 6 masks \
             the run count away and would silently under-count reads"
        );
    }

    /// The FREE-RUN arm of the same renderer: the mode really is
    /// threaded through, and on its own it drives the format stamp UP to 4 (a format-3
    /// reader must refuse a free-run bag rather than apply the lockstep
    /// contract to a stream built to violate it).
    ///
    /// The role term
    /// overrides the free-run arm, so this renderer stamps **5**, and folding
    /// raises it to the 6 asserted here. The test NAME
    /// is part of the oracle — it states the number the renderer stamps.
    #[cfg(unix)]
    #[test]
    fn a_free_run_recorder_json_stamps_free_run_and_format_six() {
        use crate::replay_engine::CoordinationMode;
        let now = Duration::from_nanos(7);
        let v: serde_json::Value =
            serde_json::from_slice(&render_recorder_json(now, CoordinationMode::FreeRun))
                .expect("valid JSON");
        assert_eq!(v["coordination"], "free_run");
        // 5, not 4 — the role term overrides the free-run arm.
        // And 6, not 5 — folding overrides both
        // (`stamp_trace_format`'s hand table pins the whole matrix).
        assert_eq!(v["trace_format"], 6);
    }

    /// The ONE resolution point, and its rule:
    /// the DEFAULT is `Lockstep` on every route, `FreeRun`
    /// is an OPT-IN, and a monolith never free-runs however hard it opts in.
    ///
    /// Every arm is a hand oracle, and the two halves are asserted TOGETHER
    /// (the mode, and the bag stamp it maps to) so the map cannot silently
    /// invert one while the other stays green.
    #[test]
    fn the_supervisor_route_resolves_free_run_only_when_opted_in() {
        use crate::multiprocess::ExecutionMode;
        // The default: no opt-in ⇒ Lockstep, on BOTH routes.
        assert_eq!(
            resolve_run_execution_mode(true, false),
            ExecutionMode::Lockstep,
            "a supervisor run WITHOUT the opt-in must keep the shipped barrier-lockstep default"
        );
        assert_eq!(
            resolve_run_execution_mode(false, false),
            ExecutionMode::Lockstep
        );
        // The opt-in: honoured ONLY where there are ranks to free-run.
        assert_eq!(
            resolve_run_execution_mode(true, true),
            ExecutionMode::FreeRun,
            "a supervisor run WITH the opt-in must free-run"
        );
        assert_eq!(
            resolve_run_execution_mode(false, true),
            ExecutionMode::Lockstep,
            "a monolith never free-runs — the opt-in is inert there (and warned, see \
             `an_inert_free_run_opt_in_is_warned_once`)"
        );
        #[cfg(unix)]
        {
            use crate::replay_engine::CoordinationMode;
            // The bag stamp is the pure map of the mode, both ways.
            assert_eq!(
                resolve_run_coordination(ExecutionMode::Lockstep),
                CoordinationMode::Lockstep
            );
            assert_eq!(
                resolve_run_coordination(ExecutionMode::FreeRun),
                CoordinationMode::FreeRun
            );
            // The monolith recording route's structural mode AGREES with what
            // the resolver answers for a monolith under every opt-in — the two
            // are one rule stated twice, and this is what keeps them one.
            for opt_in in [false, true] {
                assert_eq!(
                    resolve_run_execution_mode(false, opt_in),
                    MONOLITH_EXECUTION_MODE,
                    "the monolith recording route must stamp the same mode the resolver \
                     answers for a monolith (opt_in={opt_in})"
                );
            }
        }
    }

    /// The opt-in grammar: exact-match, and an unrecognised
    /// value keeps the DEFAULT (never silently opts in). Hand oracle over
    /// every arm of the parser, including the two accepted spellings, which
    /// are the plan enum's own serde names.
    #[test]
    fn the_execution_mode_env_parses_exactly_two_spellings_and_flags_garbage() {
        // The default, by absence or explicitly.
        assert_eq!(parse_execution_mode_env(None), (false, false));
        assert_eq!(parse_execution_mode_env(Some("")), (false, false));
        assert_eq!(parse_execution_mode_env(Some("lockstep")), (false, false));
        // The opt-in.
        assert_eq!(parse_execution_mode_env(Some("free_run")), (true, false));
        // Garbage keeps the default AND is flagged — the exact-match
        // discipline: no case-folding, no trimming, no aliases.
        for junk in [
            "FREE_RUN",
            "free-run",
            "freerun",
            " free_run",
            "1",
            "on",
            "true",
        ] {
            assert_eq!(
                parse_execution_mode_env(Some(junk)),
                (false, true),
                "{junk:?} must keep the default and be flagged"
            );
        }
        // The serde spellings and the env spellings are ONE vocabulary.
        assert_eq!(
            serde_json::to_value(crate::multiprocess::ExecutionMode::FreeRun).unwrap(),
            serde_json::json!("free_run")
        );
        assert_eq!(
            serde_json::to_value(crate::multiprocess::ExecutionMode::Lockstep).unwrap(),
            serde_json::json!("lockstep")
        );
    }

    /// A garbage opt-in value is LOUD (and still the default);
    /// every recognised value is silent.
    #[test]
    #[tracing_test::traced_test]
    fn a_garbage_execution_mode_value_warns_and_keeps_the_default() {
        assert!(!resolve_free_run_opt_in(Some("FREE_RUN")));
        assert!(logs_contain("CERULION_EXECUTION_MODE is set but not"));
        assert!(
            logs_contain("got=FREE_RUN"),
            "the offending value rides the structured `got=` field"
        );
        assert!(logs_contain("keeping the barrier-lockstep default"));
        // Anti-tautology: the recognised values must NOT produce the line.
        assert!(resolve_free_run_opt_in(Some("free_run")));
        assert!(!resolve_free_run_opt_in(Some("lockstep")));
        assert!(!resolve_free_run_opt_in(None));
        logs_assert(|lines| {
            let n = lines
                .iter()
                .filter(|l| l.contains("CERULION_EXECUTION_MODE is set but not"))
                .count();
            if n == 1 {
                Ok(())
            } else {
                Err(format!("expected exactly one garbage warn, got {n}"))
            }
        });
    }

    /// An opt-in on a run that cannot honour it is WARNED, once,
    /// naming what would make it take effect — and a supervisor run with the
    /// opt-in, or any run without it, says nothing.
    #[test]
    #[tracing_test::traced_test]
    fn an_inert_free_run_opt_in_is_warned_once() {
        note_inert_free_run_opt_in(false, true);
        assert!(logs_contain(
            "CERULION_EXECUTION_MODE=free_run is INERT on this run"
        ));
        assert!(logs_contain("executes no process groups"));
        // Anti-tautology: the three non-inert shapes are silent.
        note_inert_free_run_opt_in(true, true);
        note_inert_free_run_opt_in(true, false);
        note_inert_free_run_opt_in(false, false);
        logs_assert(|lines| {
            let n = lines
                .iter()
                .filter(|l| l.contains("is INERT on this run"))
                .count();
            if n == 1 {
                Ok(())
            } else {
                Err(format!("expected exactly one inert warn, got {n}"))
            }
        });
    }

    // =======================================================================
    // Warn/report pins: the schema-parse
    // warn attribution and report_bagd_outcome's three failure arms.
    // (signal_term's non-ESRCH kill-failure warn is NOT pinned: forcing a
    // genuine kill(2) failure needs EPERM against a foreign-uid process,
    // which is not constructible in an unprivileged test — documented here
    // instead.)
    // =======================================================================

    #[cfg(unix)]
    #[test]
    #[tracing_test::traced_test]
    fn wire_sizes_builder_warns_on_malformed_schema_yaml() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir(tmp.path().join("schemas")).unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("broken.yaml"),
            "schemas:\n  Broken:\n    fields: [not, a, map\n",
        )
        .unwrap();
        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert!(sizes.is_empty(), "the malformed file yields no entries");
        assert!(
            logs_contain("could not PARSE"),
            "a malformed workspace schema file must be WARNED with parse attribution"
        );
    }

    /// The composed-overflow class on the recorder fold: a COMPOSED-
    /// overflow store schema referenced as a nested TARGET would panic this
    /// builder inside `resolve_fixed_nested` (`ComposedInner` individually
    /// sizable, `Outer = ComposedInner[4]` overflowing only after inlining,
    /// `Wrapper` referencing `Outer` — resolving Wrapper materializes
    /// Outer). With the preflight the hostile shape records no entry and the
    /// sane sibling still sizes.
    #[cfg(unix)]
    #[test]
    fn wire_sizes_builder_survives_a_composed_overflow_nested_target() {
        let tmp = tempfile::tempdir().unwrap();
        let msg_dir = tmp.path().join("schemas").join("p1").join("msg");
        std::fs::create_dir_all(&msg_dir).unwrap();
        std::fs::write(
            msg_dir.join("ComposedInner.msg"),
            "float64[2305843009213693951] v\n",
        )
        .unwrap();
        std::fs::write(msg_dir.join("Outer.msg"), "ComposedInner[4] arr\n").unwrap();
        std::fs::write(msg_dir.join("Wrapper.msg"), "Outer o\nfloat64 w\n").unwrap();
        std::fs::write(msg_dir.join("Goal.msg"), "float64 x\n").unwrap();

        // Without the composed preflight this call PANICS materializing Outer as Wrapper's target.
        let sizes = build_workspace_schema_wire_sizes(tmp.path());

        assert!(
            !sizes.contains_key("p1/Outer"),
            "the composed overflow is preflighted out: {sizes:?}"
        );
        assert_eq!(
            sizes.get("p1/Goal").copied(),
            Some(8),
            "the sane sibling still records its real fixed size"
        );
        // The wrapper SURVIVES with its ref conservatively variable — its
        // own fixed section is just the trailing f64.
        assert_eq!(
            sizes.get("p1/Wrapper").copied(),
            Some(8),
            "the referencing schema degrades (ref variable), never panics"
        );
    }

    #[cfg(unix)]
    #[test]
    fn report_bagd_outcome_arms_have_distinct_messages() {
        let out = std::path::PathBuf::from("/tmp/report_arm_test.mcap");

        // Exited(success) → Ok.
        let mut ok_guard = spawn_fake("exit 0");
        let status = match wait_for_child_bounded(&mut ok_guard, Duration::from_secs(10)) {
            ChildExitWait::Exited(s) => s,
            other => panic!("expected exit, got {other:?}"),
        };
        assert!(
            report_bagd_outcome("g", &out, ChildExitWait::Exited(status), &mut ok_guard).is_ok()
        );

        // Exited(failure) → the INCOMPLETE error naming the bag.
        let mut fail_guard = spawn_fake("exit 3");
        let status = match wait_for_child_bounded(&mut fail_guard, Duration::from_secs(10)) {
            ChildExitWait::Exited(s) => s,
            other => panic!("expected exit, got {other:?}"),
        };
        let err = report_bagd_outcome("g", &out, ChildExitWait::Exited(status), &mut fail_guard)
            .expect_err("a failed bagd exit must be an error");
        let msg = err.to_string();
        assert!(
            msg.contains("exited with a failure") && msg.contains("report_arm_test.mcap"),
            "exit-failure arm names the failure + the bag: {msg}"
        );

        // Lost → the DISTINCT unpollable message (NOT the finalize-timeout text).
        let mut lost_guard = spawn_fake("exit 0");
        lost_guard.kill_and_reap(); // guard consumed; Lost is passed explicitly
        let err = report_bagd_outcome("g", &out, ChildExitWait::Lost, &mut lost_guard)
            .expect_err("a lost bagd must be an error");
        let msg = err.to_string();
        assert!(
            msg.contains("unpollable") && msg.contains("NOT a finalize timeout"),
            "the Lost arm must be DISTINGUISHABLE from a timeout: {msg}"
        );

        // TimedOut → the finalize-deadline message (kills + reaps the child).
        let mut slow_guard = spawn_fake("sleep 30");
        let err = report_bagd_outcome("g", &out, ChildExitWait::TimedOut, &mut slow_guard)
            .expect_err("a finalize timeout must be an error");
        let msg = err.to_string();
        assert!(
            msg.contains("did not finalize within"),
            "the TimedOut arm names the deadline: {msg}"
        );
        assert!(slow_guard.reaped(), "the TimedOut arm kills + reaps");
    }

    // =======================================================================
    // --record-cpu decision
    // table over PERMITTED core-id sets (Linux) + the non-Linux `None` mode —
    // the whole table is pure, so both OS modes are pinned on any host.
    // =======================================================================

    #[cfg(unix)]
    #[test]
    fn record_cpu_linux_mode_uses_permitted_ids_not_count() {
        use CpuPinDecision::*;

        // AUTO over a contiguous 4-core set → the highest id.
        assert_eq!(
            resolve_record_cpu(RecordCpu::Auto, Some(&[0, 1, 2, 3])).unwrap(),
            Pin(3),
            "auto picks the highest PERMITTED core"
        );
        // THE isolated-cpuset shape: a cpuset-isolated machine permits {2, 5, 9} —
        // count is 3... but even with a 4-wide isolated set the pick must be
        // the MAX PERMITTED ID, never (count - 1).
        assert_eq!(
            resolve_record_cpu(RecordCpu::Auto, Some(&[2, 5, 9, 11])).unwrap(),
            Pin(11),
            "auto on an isolated set picks the max permitted id, NOT count-1"
        );
        // <4 permitted cores → capacity-bound float (even with high ids).
        assert_eq!(
            resolve_record_cpu(RecordCpu::Auto, Some(&[2, 5, 9])).unwrap(),
            FloatCapacityBound,
            "a <4-permitted-core machine floats under auto"
        );
        assert_eq!(
            resolve_record_cpu(RecordCpu::Auto, Some(&[0])).unwrap(),
            FloatCapacityBound
        );

        // Explicit core: MEMBERSHIP, not range. A high permitted id (9 on a
        // 3-permitted-core machine) is ACCEPTED (an `n < count` check
        // would wrongly reject it)...
        assert_eq!(
            resolve_record_cpu(RecordCpu::Core(9), Some(&[2, 5, 9])).unwrap(),
            Pin(9),
            "a permitted high id must be accepted (membership, not range)"
        );
        // ...and a NON-permitted low id (0 here) is REJECTED naming the set
        // (a range check would wrongly accept it).
        let err = resolve_record_cpu(RecordCpu::Core(0), Some(&[2, 5, 9]))
            .expect_err("a non-permitted core must be rejected");
        let msg = err.to_string();
        assert!(
            msg.contains("core 0") && msg.contains("[2, 5, 9]"),
            "names the bad core + the PERMITTED set: {msg}"
        );

        // None: always floats.
        assert_eq!(
            resolve_record_cpu(RecordCpu::None, Some(&[0, 1, 2, 3])).unwrap(),
            Float
        );
    }

    /// The non-Linux (`permitted_linux = None`) mode NEVER
    /// hard-aborts — an explicit core (any value, in or out of any range) is
    /// the warn-and-float arm; auto is the silent float.
    #[cfg(unix)]
    #[test]
    fn record_cpu_nonlinux_mode_never_aborts() {
        use CpuPinDecision::*;

        assert_eq!(
            resolve_record_cpu(RecordCpu::Core(2), Option::None).unwrap(),
            FloatUnsupportedExplicit(2),
            "an explicit core on a non-pinning OS warns-and-floats"
        );
        // No inconsistency: an out-of-range id must not hard-abort on
        // macOS while an in-range one floats. Both are the same arm.
        assert_eq!(
            resolve_record_cpu(RecordCpu::Core(9999), Option::None).unwrap(),
            FloatUnsupportedExplicit(9999),
            "an absurd core id on a non-pinning OS still floats (never validated \
             where it is never consumed)"
        );
        assert_eq!(
            resolve_record_cpu(RecordCpu::Auto, Option::None).unwrap(),
            Float,
            "auto on a non-pinning OS floats silently"
        );
        assert_eq!(
            resolve_record_cpu(RecordCpu::None, Option::None).unwrap(),
            Float
        );
    }

    // The workspace schema → wire_fixed_size resolver. A fixed
    // two-`uint32` schema has a wire fixed size of 8 bytes (4+4, 4-aligned, no
    // header); a missing schemas/ dir yields an empty map (recorded size 0).
    #[cfg(unix)]
    #[test]
    fn build_workspace_schema_wire_sizes_resolves_fixed_size() {
        let tmp = tempfile::tempdir().unwrap();
        // Empty workspace (no schemas/ dir) → empty map.
        assert!(
            build_workspace_schema_wire_sizes(tmp.path()).is_empty(),
            "a workspace with no schemas/ dir yields no wire sizes"
        );
        // Add a fixed schema and re-resolve.
        std::fs::create_dir(tmp.path().join("schemas")).unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("blob.yaml"),
            "schemas:\n  Blob:\n    fields:\n      uint32 a:\n      uint32 b:\n",
        )
        .unwrap();
        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("Blob").copied(),
            Some(8),
            "two uint32 fields → wire_fixed_size 8; got {sizes:?}"
        );
    }

    // ======================================================================
    // msg-store parity, surface 2: the recorded wire-size map must include
    // `.msg` store types. With no entry in the map a store-typed topic records
    // `wire_fixed_size` 0. Hand-computed byte
    // oracles throughout (8-byte f64s, 4-byte u32s, #[repr(C)] padding).
    // ======================================================================

    /// Write one `.msg` store file under `<root>/schemas/<pkg>/msg/`.
    #[cfg(unix)]
    fn write_store_msg(root: &std::path::Path, pkg: &str, type_name: &str, text: &str) {
        let dir = root.join("schemas").join(pkg).join("msg");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join(format!("{type_name}.msg")), text).unwrap();
    }

    /// The fold agrees with the replay registry:
    /// with store `p/Type` + `other/Type` + a
    /// workspace YAML slash entry `p/Type`, bare `Type` is AMBIGUOUS at port
    /// resolution — `SchemaStore::matches_bare_name` sees both store files
    /// whatever the YAML shadows by string — so `graph validate` REFUSES a
    /// port declared as `Type` (the PREMISE assert below) and no bag can
    /// carry one. Serving `other/Type`'s size under that alias (a
    /// "sole serving bearer" rule) while the replay registry answers
    /// `None` for the same name would be two verdicts for an output that cannot
    /// exist. The fold mirrors port resolution — NO alias; the
    /// qualified keys still serve the YAML string winner and the store
    /// sibling.
    #[cfg(unix)]
    #[test]
    fn r16_an_ambiguous_parsed_bare_name_gets_no_alias_whatever_yaml_shadows() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "p", "Type", "uint32 a\n");
        write_store_msg(tmp.path(), "other", "Type", "uint32 a\n");
        std::fs::write(
            tmp.path().join("schemas").join("ptype.yaml"),
            "schemas:\n  p/Type:\n    fields:\n      uint32 b:\n      uint32 c:\n",
        )
        .unwrap();

        // PREMISE: port resolution refuses bare `Type` here — both store
        // files bear it, and the YAML string shadow does not enter the claim.
        let schemas_dir = tmp.path().join("schemas");
        let err = crate::schema_cmd::resolve_port_schema(&schemas_dir, "Type")
            .expect_err("bare `Type` is ambiguous at port resolution");
        assert!(err.to_string().contains("ambiguous"), "got: {err}");
        assert!(
            crate::schema_cmd::port_schema_exists(&schemas_dir, "Type").is_err(),
            "graph validation refuses the bare port the same way"
        );

        let sizes = build_workspace_schema_wire_sizes(tmp.path());

        assert_eq!(
            sizes.get("Type"),
            None,
            "a bare name port resolution refuses gets NO alias — the fold, the \
             registry and validation agree; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("p/Type").copied(),
            Some(8),
            "the YAML winner serves the shadowed string (later-wins)"
        );
        assert_eq!(sizes.get("other/Type").copied(), Some(4));
    }

    /// Schema identity:
    /// with ONLY store `p/Type` + a slash-named YAML entry `p/Type`, keeping
    /// the store's bare `Type` alias ("a slash-named YAML entry
    /// claims only the STRING, never the BARE name") would match a validation
    /// that bound bare `Type` to the store — while serving and replay
    /// resolve the string `p/Type` to the YAML twin, so a bag recorded from
    /// that port would be refused at replay as schema drift. Validation
    /// REFUSES the bare name (the qualified spelling belongs to the
    /// workspace tier — `bare_store_port_binding`), so the fold serves no
    /// alias for it; the qualified string is the YAML winner's.
    #[cfg(unix)]
    #[test]
    fn r26_a_sole_store_bearer_whose_string_a_yaml_entry_claims_is_refused_and_gets_no_alias() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "p", "Type", "uint32 a\n");
        std::fs::write(
            tmp.path().join("schemas").join("ptype.yaml"),
            "schemas:\n  p/Type:\n    fields:\n      uint32 b:\n      uint32 c:\n",
        )
        .unwrap();

        // PREMISE: validation refuses the bare name, on both port surfaces.
        let schemas_dir = tmp.path().join("schemas");
        let err = crate::schema_cmd::resolve_port_schema(&schemas_dir, "Type")
            .expect_err("bare `Type` is refused: its qualified string is the YAML tier's");
        assert!(
            err.to_string()
                .contains("'p/Type' is ambiguous in this workspace — defined by:")
                && err
                    .to_string()
                    .contains("schemas/ptype.yaml (entry p/Type)")
                && err.to_string().contains("schemas/p/msg/Type.msg (store)"),
            "got: {err}"
        );
        assert!(
            crate::schema_cmd::port_schema_exists(&schemas_dir, "Type").is_err(),
            "graph validation refuses the bare port the same way"
        );

        let sizes = build_workspace_schema_wire_sizes(tmp.path());

        assert_eq!(
            sizes.get("Type"),
            None,
            "no alias for a bare name validation refuses — the fold, the registry, \
             serving and validation agree; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("p/Type").copied(),
            Some(8),
            "the YAML winner still serves the qualified string"
        );
    }

    /// The hash fold's declared moment, covered by a
    /// test instead of a filter: the composing folds judge the wire
    /// ceiling at the RESOLVED moment only, so an over-ceiling DECLARATION
    /// is still present while `resolve_fixed_nested` runs. That is safe by
    /// arithmetic — resolution only ever ADDS a fixed target's bytes to the
    /// parent, so every schema that resolved through an over-ceiling target
    /// is itself over the ceiling and leaves at the resolved retain — and
    /// this arm pins the consequence: no
    /// SURVIVOR is influenced. `Huge` is over the ceiling as declared,
    /// `Outer` composes over through it, `Wrapper` references `Outer`, and
    /// `Many` carries `Huge[]` (a variable reference, hashed by name, whose
    /// closure escapes once `Huge` is gone); all four are OMITTED from both
    /// composing folds, while `Clean` and the nested `Pair` record the
    /// IDENTICAL hash and size they record in a control workspace that
    /// never declared the hostile shapes. A declared-moment retain
    /// would pass this arm's omission half too — what it breaks is a nested
    /// target dropped BEFORE the composed scrub (`Outer` served as size 0);
    /// the sizes fold's composed-overflow arm above is the test for
    /// that, this one is for the ceiling.
    #[cfg(unix)]
    #[test]
    fn r29_an_over_ceiling_declaration_is_omitted_by_the_composing_folds_and_influences_no_survivor(
    ) {
        const AT: usize = u32::MAX as usize - 32;
        let hostile = tempfile::tempdir().unwrap();
        let control = tempfile::tempdir().unwrap();
        for root in [hostile.path(), control.path()] {
            write_store_msg(root, "p29", "Clean", "float64 y\n");
            write_store_msg(root, "p29", "Pair", "Clean c\nuint32 k\n");
            // `Many` is declared on BOTH sides; only the hostile side also
            // declares its element type, so the control is "the same
            // reference, unresolvable" — what the hash fold must reduce
            // the hostile side to.
            write_store_msg(root, "p29", "Many", "Huge[] hs\nuint8 tag\n");
        }
        write_store_msg(
            hostile.path(),
            "p29",
            "Huge",
            &format!("uint8[{}] a\n", AT + 1),
        );
        write_store_msg(hostile.path(), "p29", "Outer", "Huge h\nfloat64 x\n");
        write_store_msg(hostile.path(), "p29", "Wrapper", "Outer o\nfloat64 w\n");

        let hashes = build_workspace_schema_hashes(hostile.path());
        let control_hashes = build_workspace_schema_hashes(control.path());
        let sizes = build_workspace_schema_wire_sizes(hostile.path());
        let control_sizes = build_workspace_schema_wire_sizes(control.path());

        for name in ["p29/Huge", "p29/Outer", "p29/Wrapper", "p29/Many"] {
            assert!(
                !hashes.contains_key(name),
                "'{name}' must be OMITTED from the hash map, never hashed over an \
                 over-ceiling target: {hashes:?}"
            );
        }
        for name in ["p29/Huge", "p29/Outer", "p29/Wrapper"] {
            assert!(
                !sizes.contains_key(name),
                "'{name}' must be OMITTED from the recorded size map, never sized \
                 at 0: {sizes:?}"
            );
        }
        // A VARIABLE reference carries no fixed bytes, so `Many` legitimately
        // records its one fixed byte on both sides: the over-ceiling element
        // declaration changed nothing about it.
        assert_eq!(sizes.get("p29/Many").copied(), Some(1), "{sizes:?}");
        assert_eq!(sizes.get("p29/Many"), control_sizes.get("p29/Many"));
        assert!(
            !control_hashes.contains_key("p29/Many"),
            "the control's `Many` escapes too (its element type is undeclared)"
        );
        for name in ["p29/Clean", "p29/Pair"] {
            assert_eq!(
                hashes.get(name),
                control_hashes.get(name),
                "'{name}' hashes exactly as in the control workspace — the hostile \
                 declarations influenced no survivor"
            );
            assert!(hashes.contains_key(name), "'{name}' survives: {hashes:?}");
            assert_eq!(
                sizes.get(name),
                control_sizes.get(name),
                "'{name}' sizes exactly as in the control workspace"
            );
        }
        assert_eq!(
            sizes.get("p29/Pair").copied(),
            Some(16),
            "the nested survivor still RESOLVED (f64 + u32, padded to the f64 \
             stride = 16 bytes), so the control equality is not vacuous"
        );
        let mut keys: Vec<_> = hashes.keys().collect();
        let mut control_keys: Vec<_> = control_hashes.keys().collect();
        keys.sort();
        control_keys.sort();
        assert_eq!(
            keys, control_keys,
            "the hash map's key set is exactly the control's — nothing hostile survived"
        );
    }
    /// Wire-size validation: a
    /// ceiling judging the fixed section alone (`<= u32::MAX`) is wrong, because the frame
    /// also carries the 32-byte header and one 8-byte offset entry per
    /// variable field, so a fixed section of `u32::MAX` bytes would be recorded
    /// as a descriptor no publisher can emit. Both sides of the boundary on
    /// the RESOLVED fold: a fixed section exactly at `u32::MAX − 32`
    /// (`At`) and at `u32::MAX − 40` beside one string (`VarAt`) record
    /// their exact sizes; one byte past each (`Over`, `VarOver`) and the
    /// extreme (`Max`, exactly `u32::MAX`) are omitted. Nested
    /// inlining is judged at the resolved moment: `WrapAt` (a `uint8` run
    /// plus an inlined 8-byte `Small`, padded, lands at `u32::MAX − 39`)
    /// records, `WrapOver` (one byte more of run, so padding + inlining
    /// land one past the ceiling) is omitted; `Tight` pins that a reference
    /// resolution INLINES is counted as fixed bytes and never as an offset
    /// entry (the fold has no declared-moment check — the DECLARED floor
    /// itself is pinned on the `schema info` and serving surfaces in
    /// `msg_store_parity_test`); and `VarNestAt` / `VarNestOver` pin the
    /// RESOLVED moment's EXACT count: `Blob` has a string, so `Blob b` stays
    /// a real offset entry after resolution, which the declared floor would
    /// not count — at `u32::MAX − 40` it records, one byte more is omitted.
    #[cfg(unix)]
    #[test]
    fn r26_the_fold_ceiling_counts_the_header_and_the_offset_table_on_both_sides() {
        const AT: usize = u32::MAX as usize - 32;
        const VAR_AT: usize = AT - 8;
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "p26", "At", &format!("uint8[{AT}] a\n"));
        write_store_msg(tmp.path(), "p26", "Over", &format!("uint8[{}] a\n", AT + 1));
        write_store_msg(
            tmp.path(),
            "p26",
            "Max",
            &format!("uint8[{}] a\n", u32::MAX),
        );
        write_store_msg(
            tmp.path(),
            "p26",
            "VarAt",
            &format!("uint8[{VAR_AT}] a\nstring s\n"),
        );
        write_store_msg(
            tmp.path(),
            "p26",
            "VarOver",
            &format!("uint8[{}] a\nstring s\n", VAR_AT + 1),
        );
        write_store_msg(tmp.path(), "p26", "Small", "uint64 v\n");
        write_store_msg(
            tmp.path(),
            "p26",
            "WrapAt",
            &format!("uint8[{}] a\nSmall s\n", AT - 16),
        );
        write_store_msg(
            tmp.path(),
            "p26",
            "WrapOver",
            &format!("uint8[{}] a\nSmall s\n", AT - 8),
        );
        write_store_msg(tmp.path(), "p26", "Tiny", "uint32 v\n");
        write_store_msg(
            tmp.path(),
            "p26",
            "Tight",
            &format!("uint8[{}] a\nTiny t\n", AT - 7),
        );
        write_store_msg(tmp.path(), "p26", "Blob", "string s\n");
        write_store_msg(
            tmp.path(),
            "p26",
            "VarNestAt",
            &format!("uint8[{VAR_AT}] a\nBlob b\n"),
        );
        write_store_msg(
            tmp.path(),
            "p26",
            "VarNestOver",
            &format!("uint8[{}] a\nBlob b\n", VAR_AT + 1),
        );

        let sizes = build_workspace_schema_wire_sizes(tmp.path());

        for (name, size) in [
            ("p26/At", AT),
            ("p26/VarAt", VAR_AT),
            // AT − 16 = …247, the u64 lands at …248 (align 8), ends …256.
            ("p26/WrapAt", AT - 7),
            // AT − 7 = …256, the u32 lands there (align 4), ends …260.
            ("p26/Tight", AT - 3),
            // The still-variable `Blob b` is one entry: the run is the whole
            // fixed section (the reference adds no bytes and no alignment).
            ("p26/VarNestAt", VAR_AT),
        ] {
            assert_eq!(
                sizes.get(name).copied(),
                Some(u32::try_from(size).unwrap()),
                "'{name}': at or under the ceiling records its exact size; got {sizes:?}"
            );
        }
        for name in [
            "p26/Over",
            "p26/VarOver",
            "p26/Max",
            "p26/WrapOver",
            "p26/VarNestOver",
        ] {
            assert_eq!(
                sizes.get(name),
                None,
                "'{name}': a frame prefix past the u32 total_size is OMITTED, never \
                 recorded; got {sizes:?}"
            );
        }
    }

    /// The string-shadow fallback must
    /// judge bare-name AMBIGUITY over the PRE-retain parsed store — the
    /// set `resolve_port_schema`'s store tier consults. Here `a9/Type`
    /// (composed overflow) is removed by the sizing retain, leaving
    /// `b9/Type` the sole string-shadowed survivor — but the store ON DISK
    /// still holds both, so port resolution refuses bare `Type` as
    /// ambiguous, and the fallback must NOT resurrect an alias that
    /// silently picks the surviving package.
    #[cfg(unix)]
    #[test]
    fn r12_a_retain_thinned_ambiguity_does_not_resurrect_a_bare_alias() {
        let tmp = tempfile::tempdir().unwrap();
        // `Filler` is representable (~4 GiB, seven bytes under the wire
        // ceiling `u32::MAX − 32` — a declared-past-u32
        // ingredient is rejected on every
        // surface); `a9/Type` composes an ARITHMETIC overflow through it.
        write_store_msg(tmp.path(), "a9", "Filler", "float64[536870907] v\n");
        write_store_msg(tmp.path(), "a9", "Type", "Filler[8589934592] arr\n");
        write_store_msg(tmp.path(), "b9", "Type", "uint32 a\n");
        std::fs::write(
            tmp.path().join("schemas").join("btype.yaml"),
            "schemas:\n  b9/Type:\n    fields:\n      uint32 b:\n      uint32 c:\n",
        )
        .unwrap();

        let sizes = build_workspace_schema_wire_sizes(tmp.path());

        assert_eq!(
            sizes.get("Type"),
            None,
            "bare `Type` was ambiguous over the parsed store (a9 + b9) — \
             the retain-thinned survivor must not be silently picked; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("b9/Type").copied(),
            Some(8),
            "the qualified path still works (the YAML string winner serves)"
        );
        assert!(
            sizes.contains_key("Filler"),
            "the serving-winner alias path is untouched (control)"
        );
    }

    /// THE surface-2 parity pin (with no entry the port records 0):
    /// a store type maps under its qualified name AND — being the only
    /// claimant of its bare name — under a bare alias.
    #[cfg(unix)]
    #[test]
    fn wire_sizes_include_msg_store_types() {
        let tmp = tempfile::tempdir().unwrap();
        // float64 x + float64 y → 16 bytes, hand oracle.
        write_store_msg(tmp.path(), "nav_pkg", "Goal", "float64 x\nfloat64 y\n");
        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("nav_pkg/Goal").copied(),
            Some(16),
            "store type under its qualified key; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("Goal").copied(),
            Some(16),
            "unique bare name gets an alias; got {sizes:?}"
        );
    }

    /// YAML-vs-store precedence for a shared stem: the BARE key belongs to
    /// the YAML schema (workspace-YAML-first), the qualified key to the
    /// store type.
    #[cfg(unix)]
    #[test]
    fn wire_sizes_yaml_wins_the_bare_key_over_the_store() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join("schemas")).unwrap();
        // YAML Goal: one uint32 → 4 bytes. Store nav_pkg/Goal: 16 bytes.
        std::fs::write(
            tmp.path().join("schemas").join("goal.yaml"),
            "schemas:\n  Goal:\n    fields:\n      uint32 a:\n",
        )
        .unwrap();
        write_store_msg(tmp.path(), "nav_pkg", "Goal", "float64 x\nfloat64 y\n");
        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("Goal").copied(),
            Some(4),
            "YAML wins the bare key"
        );
        assert_eq!(
            sizes.get("nav_pkg/Goal").copied(),
            Some(16),
            "the store type keeps its qualified key"
        );
    }

    /// A bare name defined by TWO store packages gets NO alias — a lookup
    /// map must never silently pick a package. Both qualified keys serve.
    #[cfg(unix)]
    #[test]
    fn wire_sizes_ambiguous_store_bare_name_gets_no_alias() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "pkga", "Goal", "float64 x\n"); // 8
        write_store_msg(tmp.path(), "pkgb", "Goal", "uint32 a\n"); // 4
        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(sizes.get("pkga/Goal").copied(), Some(8));
        assert_eq!(sizes.get("pkgb/Goal").copied(), Some(4));
        assert!(
            !sizes.contains_key("Goal"),
            "an ambiguous bare name must have NO alias; got {sizes:?}"
        );
    }

    /// A store type nesting a SAME-PACKAGE store type by bare ref (the
    /// same-package rule) resolves before sizing: Outer = Inner (8) + f64 (8)
    /// → 16, not the unresolved 8.
    #[cfg(unix)]
    #[test]
    fn wire_sizes_resolve_same_package_store_nesting() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "nav_pkg", "Inner", "float64 v\n");
        write_store_msg(tmp.path(), "nav_pkg", "Outer", "Inner i\nfloat64 w\n");
        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("nav_pkg/Outer").copied(),
            Some(16),
            "the fixed-nested Inner must inline (8 + 8); got {sizes:?}"
        );
    }

    /// A hostile-but-parseable declaration (YAML or store) must not PANIC
    /// the recorder's map builder — the YAML arm panics without
    /// the sizing preflight; the sane sibling still sizes.
    #[cfg(unix)]
    #[test]
    fn wire_sizes_hostile_declarations_are_skipped_never_a_panic() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join("schemas")).unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("hostile.yaml"),
            "schemas:\n  HostileY:\n    fields:\n      float64[18446744073709551615] a:\n",
        )
        .unwrap();
        write_store_msg(
            tmp.path(),
            "nav_pkg",
            "HostileM",
            "float64[2305843009213693952] a\n",
        );
        write_store_msg(tmp.path(), "nav_pkg", "Goal", "float64 x\nfloat64 y\n");
        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert!(!sizes.contains_key("HostileY"), "hostile YAML skipped");
        assert!(
            !sizes.contains_key("nav_pkg/HostileM"),
            "hostile store skipped"
        );
        assert_eq!(
            sizes.get("nav_pkg/Goal").copied(),
            Some(16),
            "sibling survives"
        );
    }

    /// A port labelled `Goal` beside a `Goal.yaml` declaring only
    /// `Other` is a valid port (the YAML stem tier) that the gateway bound to
    /// `Other`'s document — so the fold must not record 0 for
    /// it. The fold binds the stem to the file's sole entry (`Other` =
    /// one u32 → 4, hand oracle), end to end through `resolve_recorded_topics`;
    /// a multi-entry `Multi.yaml` stem binds nothing (0, loud) — the ONE
    /// message every surface uses.
    #[cfg(unix)]
    #[test]
    #[tracing_test::traced_test]
    fn r23_a_stem_claimed_port_records_the_sole_entrys_layout_size() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "nav23", "Goal", "float64 x\nfloat64 y\n");
        std::fs::write(
            tmp.path().join("schemas").join("Goal.yaml"),
            "schemas:\n  Other:\n    fields:\n      uint32 a:\n",
        )
        .unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("Multi.yaml"),
            "schemas:\n  A:\n    fields:\n      uint32 a:\n  B:\n    fields:\n      uint32 b:\n",
        )
        .unwrap();

        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("Goal").copied(),
            Some(4),
            "the stem binds the sole entry's real layout size; got {sizes:?}"
        );
        assert_eq!(sizes.get("Other").copied(), Some(4));
        assert_eq!(
            sizes.get("nav23/Goal").copied(),
            Some(16),
            "the store keeps its qualified key"
        );
        assert_eq!(sizes.get("Multi"), None, "a multi-entry stem binds nothing");
        assert!(
            logs_contain("claims this name ambiguously"),
            "the multi-entry stem is refused loudly by design"
        );

        // End to end: the recorded descriptor carries the bound size.
        let yaml = "name: r23\nprefix: r23\nnodes:\n  - id: n\n    type: n\n    \
                    outputs:\n      - name: o\n        schema: Goal\n";
        let config = cerulion_core::graph::parse_graph(yaml).expect("valid graph");
        use cerulion_core::graph::node::{NodeInfo, OutputMeta};
        let mut infos: indexmap::IndexMap<String, NodeInfo> = indexmap::IndexMap::new();
        infos.insert(
            "n".to_string(),
            NodeInfo::with_meta(vec![], vec![OutputMeta::new("o".to_string(), 0xABCD, None)]),
        );
        let recorded = resolve_recorded_topics(tmp.path(), &config, &infos).expect("resolves");
        assert_eq!(
            recorded[0].wire_fixed_size, 4,
            "recorded through the stem binding"
        );
    }

    /// Schema provenance under the
    /// ambiguity-refusal rule: the stem's sole entry `Other`
    /// is ALSO declared by a lexically-later file with a DIFFERENT layout.
    /// Neither the later file's size (8) nor the stem owner's (4) is recorded for the port
    /// `Goal`: BOTH
    /// names are refused — `Other` a duplicate, `Goal` a stem bound to an
    /// ambiguous name — so validation refuses the port (premise) and the
    /// recorded wire-size map carries neither. End to end through
    /// `resolve_recorded_topics`.
    #[cfg(unix)]
    #[test]
    fn r27_a_stem_whose_sole_entry_is_duplicated_elsewhere_records_nothing() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join("schemas")).unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("Goal.yaml"),
            "schemas:\n  Other:\n    fields:\n      uint32 a:\n",
        )
        .unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("zz_other.yaml"),
            "schemas:\n  Other:\n    fields:\n      uint32 z:\n      uint32 y:\n",
        )
        .unwrap();
        // PREMISE: `Goal.yaml` names exactly ONE file, so the SPELLING
        // surfaces resolve it (`workspace_lookup`) — while `Other`,
        // declared by two files, is refused there. What no MAP can do is pick
        // WHICH definition a channel labelled `Goal` carries, which is what
        // this test pins.
        let dir = tmp.path().join("schemas");
        assert!(crate::schema_cmd::port_schema_exists(&dir, "Goal").unwrap());
        let other_err = crate::schema_cmd::port_schema_exists(&dir, "Other")
            .expect_err("the duplicate entry is refused")
            .to_string();
        assert!(
            other_err
                .contains("schemas/Goal.yaml (entry Other), schemas/zz_other.yaml (entry Other)"),
            "got: {other_err}"
        );

        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("Goal"),
            None,
            "a refused name records nothing; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("Other"),
            None,
            "the duplicate entry records nothing either — never a last-wins winner"
        );

        // End to end: the recorded descriptor carries 0 (the unknown-size
        // attribution) — the fold never guesses a document for a port
        // validation refuses.
        let yaml = "name: r27\nprefix: r27\nnodes:\n  - id: n\n    type: n\n    \
                    outputs:\n      - name: o\n        schema: Goal\n";
        let config = cerulion_core::graph::parse_graph(yaml).expect("valid graph");
        use cerulion_core::graph::node::{NodeInfo, OutputMeta};
        let mut infos: indexmap::IndexMap<String, NodeInfo> = indexmap::IndexMap::new();
        infos.insert(
            "n".to_string(),
            NodeInfo::with_meta(vec![], vec![OutputMeta::new("o".to_string(), 0x2727, None)]),
        );
        let recorded = resolve_recorded_topics(tmp.path(), &config, &infos).expect("resolves");
        assert_eq!(
            recorded[0].wire_fixed_size, 0,
            "recorded 0 — never a guessed document"
        );
    }

    /// The second SCHEMA_PROVENANCE shape: the stem's sole entry
    /// is a slash-named YAML `p/Other` whose RESOLVED fixed section composes
    /// past the u32 wire ceiling (dropped by the resolved retain), beside a
    /// VALID store `p/Other`. A string-keyed stem binding would find the store's size under the
    /// surviving string and record it for the YAML-typed port `Goal`; the
    /// owner-qualified lookup records nothing (0 — the unknown-size
    /// attribution), and the string `p/Other` itself — which validation
    /// binds to the YAML tier — is MASKED rather than served from the store.
    /// The store keeps nothing under that string; the chain's `Inner` (8 MiB,
    /// representable) still records.
    #[cfg(unix)]
    #[test]
    #[tracing_test::traced_test]
    fn r24_a_dropped_stem_owner_beside_a_surviving_store_key_records_nothing() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "p", "Other", "uint32 a\n");
        std::fs::write(
            tmp.path().join("schemas").join("Goal.yaml"),
            "schemas:\n  p/Other:\n    fields:\n      Inner[1048576] arr:\n",
        )
        .unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("chain.yaml"),
            "schemas:\n  Inner:\n    fields:\n      float64[1048576] v:\n",
        )
        .unwrap();
        // PREMISE: validation binds `Goal` (stem) to the YAML tier. The
        // QUALIFIED spelling `p/Other` is the YAML/store TWIN, which the one
        // workspace lookup refuses outright — so the fold below is
        // the only surface left that has to say what it recorded for the
        // stem-typed port, which is what this test pins.
        let dir = tmp.path().join("schemas");
        assert!(matches!(
            crate::schema_cmd::resolve_port_schema(&dir, "Goal")
                .unwrap()
                .provenance,
            crate::schema_cmd::PortSchemaProvenance::Workspace { .. }
        ));
        let twin = crate::schema_cmd::resolve_port_schema(&dir, "p/Other")
            .expect_err("a YAML definition the .msg store also spells is refused")
            .to_string();
        assert!(
            twin.contains("'p/Other' is ambiguous in this workspace — defined by:")
                && twin.contains("schemas/p/msg/Other.msg (store)"),
            "got: {twin}"
        );

        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("Goal"),
            None,
            "the owner was dropped — never the store twin's size; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("p/Other"),
            None,
            "a string the YAML tier claims is never served from the store"
        );
        assert_eq!(sizes.get("Inner").copied(), Some(8 * 1_048_576));
        assert!(
            logs_contain("exceeds the u32 wire total_size"),
            "the owner's drop is loud"
        );

        let yaml = "name: r24\nprefix: r24\nnodes:\n  - id: n\n    type: n\n    \
                    outputs:\n      - name: o\n        schema: Goal\n";
        let config = cerulion_core::graph::parse_graph(yaml).expect("valid graph");
        use cerulion_core::graph::node::{NodeInfo, OutputMeta};
        let mut infos: indexmap::IndexMap<String, NodeInfo> = indexmap::IndexMap::new();
        infos.insert(
            "n".to_string(),
            NodeInfo::with_meta(vec![], vec![OutputMeta::new("o".to_string(), 0xABCD, None)]),
        );
        let recorded = resolve_recorded_topics(tmp.path(), &config, &infos).expect("resolves");
        assert_eq!(
            recorded[0].wire_fixed_size, 0,
            "recorded 0 with the unknown-size attribution, never the store's 4"
        );
    }

    /// The hash map's file-stem rule, applied to the size map: a
    /// `schemas/Goal.yaml` that parses but declares `Other` still claims bare
    /// `Goal` for the YAML tier at port resolution (the file-STEM tier), so a
    /// graph output `Goal` is YAML-typed — the fold must withhold the store
    /// alias `Goal` → `nav21/Goal` (otherwise it would serve the store's size under
    /// a YAML-typed output's name). The YAML entry keeps its own key, the
    /// store its qualified key.
    #[cfg(unix)]
    #[test]
    fn r21_a_yaml_file_stem_claim_withholds_the_store_alias() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(tmp.path(), "nav21", "Goal", "float64 x\nfloat64 y\n");
        std::fs::write(
            tmp.path().join("schemas").join("Goal.yaml"),
            "schemas:\n  Other:\n    fields:\n      uint32 a:\n",
        )
        .unwrap();
        // PREMISE: bare `Goal` is claimed by the YAML tier (the file stem) —
        // and the `.msg` store spells it too, which is the TWIN the one
        // workspace lookup refuses outright. Either way the store
        // alias is not the stem-typed port's to bind, which is what the fold
        // below must withhold.
        let err = crate::schema_cmd::resolve_port_schema(&tmp.path().join("schemas"), "Goal")
            .expect_err("a stem file the store also spells is the refused twin")
            .to_string();
        assert!(
            err.contains("'Goal' is ambiguous in this workspace — defined by:")
                && err.contains("schemas/Goal.yaml (file stem; entries: Other)")
                && err.contains("schemas/nav21/msg/Goal.msg (store)"),
            "got: {err}"
        );

        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        // The stem binds the sole entry's size (4) — never the
        // store's (16), the hole this arm was written for.
        assert_eq!(
            sizes.get("Goal").copied(),
            Some(4),
            "the YAML-claimed bare name records the stem's sole entry, never the store; got {sizes:?}"
        );
        assert_eq!(sizes.get("Other").copied(), Some(4));
        assert_eq!(sizes.get("nav21/Goal").copied(), Some(16));
    }

    /// A HOSTILE
    /// `p1/Type` is still a PARSED store file, so port resolution sees two
    /// bearers of bare `Type` and REFUSES the name (the PREMISE assert) —
    /// the retain drops `p1/Type` from the SIZING set, not from the store a
    /// graph resolves against. Serving `p2/Type`'s size under the alias
    /// would answer a lookup no validated graph can make while the replay
    /// registry says `None`; the fold says `None` too. `p2/Type` keeps
    /// its qualified key.
    #[cfg(unix)]
    #[test]
    fn r16_a_hostile_sibling_still_makes_the_bare_name_ambiguous_for_the_fold() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(
            tmp.path(),
            "p1",
            "Type",
            "float64[18446744073709551615] a\n",
        );
        write_store_msg(tmp.path(), "p2", "Type", "uint32 a\n"); // 4 bytes
                                                                 // PREMISE: the parsed store bears `Type` twice — port resolution
                                                                 // refuses it regardless of which bearer is sizable.
        let err = crate::schema_cmd::resolve_port_schema(&tmp.path().join("schemas"), "Type")
            .expect_err("bare `Type` is ambiguous at port resolution");
        assert!(err.to_string().contains("ambiguous"), "got: {err}");

        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert!(
            !sizes.contains_key("p1/Type"),
            "the hostile package is dropped"
        );
        assert_eq!(sizes.get("p2/Type").copied(), Some(4));
        assert_eq!(
            sizes.get("Type"),
            None,
            "no alias for a bare name port resolution refuses; got {sizes:?}"
        );
    }

    /// Two builds over one workspace agree exactly (Principle #7).
    #[cfg(unix)]
    #[test]
    fn wire_sizes_are_deterministic_across_builds() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join("schemas")).unwrap();
        std::fs::write(
            tmp.path().join("schemas").join("goal.yaml"),
            "schemas:\n  Goal:\n    fields:\n      uint32 a:\n",
        )
        .unwrap();
        write_store_msg(tmp.path(), "nav_pkg", "Goal", "float64 x\nfloat64 y\n");
        let a = build_workspace_schema_wire_sizes(tmp.path());
        let b = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(a, b);
    }

    /// A recording fold that resolved store
    /// and YAML but NOT the built-ins, while replay's registry combines all
    /// three, would let a store schema whose fixed-nested ref targets a built-in
    /// record only its own primitives at record time yet resolve the
    /// full inlined layout at replay. HAND ORACLE: `builtin_interfaces/Time`
    /// = `int32 sec` + `uint32 nanosec` = 8 bytes (align 4), then `float64
    /// v` (align 8 → offset 8) = 16. Without the built-in tier the fold records 8 (the
    /// unresolved ref contributes nothing); emptying the
    /// built-in tier at the fold fails this test with exactly that.
    #[cfg(unix)]
    #[test]
    fn r14_a_store_type_nesting_a_builtin_records_the_size_replay_resolves() {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(
            tmp.path(),
            "nav14",
            "Stamped",
            "builtin_interfaces/Time stamp\nfloat64 v\n",
        );

        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        assert_eq!(
            sizes.get("nav14/Stamped").copied(),
            Some(16),
            "the built-in nested target must inline into the recorded size; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("Stamped").copied(),
            Some(16),
            "the unique bare alias serves the same resolved size"
        );
        assert!(
            !sizes.contains_key("builtin_interfaces/Time"),
            "built-ins resolve REFERENCES only — the map serves workspace definitions"
        );

        // The RECORDED descriptor, through the real seam …
        let yaml = "name: r14\nprefix: r14\nnodes:\n  - id: n\n    type: n\n    \
                    outputs:\n      - name: o\n        schema: nav14/Stamped\n";
        let config = cerulion_core::graph::parse_graph(yaml).expect("valid graph");
        use cerulion_core::graph::node::{NodeInfo, OutputMeta};
        let mut infos: indexmap::IndexMap<String, NodeInfo> = indexmap::IndexMap::new();
        infos.insert(
            "n".to_string(),
            NodeInfo::with_meta(vec![], vec![OutputMeta::new("o".to_string(), 0xABCD, None)]),
        );
        let recorded = resolve_recorded_topics(tmp.path(), &config, &infos).expect("resolves");
        assert_eq!(recorded.len(), 1);
        assert_eq!(
            recorded[0].wire_fixed_size, 16,
            "the recorded descriptor carries the REAL inlined size"
        );

        // … equals what REPLAY resolves for the same topic — the surface this
        // must agree with (both are ALSO pinned to the hand oracle,
        // so the equality is a cross-check, never a self-compare).
        let reg = crate::replay_field_registry::FieldRegistry::from_graph(&config, tmp.path());
        let replay_size = reg
            .decoder_for("/r14/n/o")
            .expect("replay resolves the store type")
            .root_layout()
            .expect("replay materializes its layout")
            .fixed_size;
        assert_eq!(
            replay_size, 16,
            "replay's resolved layout is the oracle's 16"
        );
        assert_eq!(
            usize::try_from(recorded[0].wire_fixed_size).unwrap(),
            replay_size,
            "record-time descriptor == replay-time layout"
        );
    }

    /// The fold must not SATURATE an
    /// over-u32 fixed section to `u32::MAX` while `schema info` REJECTS
    /// the same schema. Three shapes, every one OMITTED on BOTH
    /// surfaces through the ONE shared ceiling: a DECLARED overshoot
    /// (`Huge`, 2^64 − 8 bytes — passes the checked recipe, fails the
    /// ceiling); a COMPOSED overshoot of representable members (`Outer =
    /// Inner[2]`, `Inner` 7 bytes under the ceiling); and a VARIABLE
    /// schema whose fixed section composes past it (`VarOuter`). `Inner`
    /// itself and a sane sibling still serve their exact sizes.
    #[cfg(unix)]
    #[test]
    fn r14_an_unrepresentable_fixed_section_is_omitted_at_the_fold_exactly_as_schema_info_rejects_it(
    ) {
        let tmp = tempfile::tempdir().unwrap();
        write_store_msg(
            tmp.path(),
            "nav14",
            "Huge",
            "float64[2305843009213693951] v\n",
        );
        write_store_msg(tmp.path(), "nav14", "Inner", "float64[536870907] v\n");
        write_store_msg(tmp.path(), "nav14", "Outer", "Inner[2] arr\n");
        write_store_msg(tmp.path(), "nav14", "VarOuter", "Inner[2] arr\nstring s\n");
        write_store_msg(tmp.path(), "nav14", "Goal", "float64 x\n");
        // A valid sibling bearing the SAME bare name as the omitted
        // `nav14/VarOuter`: two PARSED bearers make bare `VarOuter` ambiguous
        // at port resolution, so the fold serves NO alias — the
        // sibling keeps its qualified key.
        write_store_msg(tmp.path(), "other14", "VarOuter", "uint32 a\n");
        // A workspace YAML entry composing past the ceiling through the
        // store type — the `schema info` YAML-entry reader (layout
        // enrichment) applies the same resolved-size ceiling as the store
        // reader; the fold omits it too.
        std::fs::write(
            tmp.path().join("schemas").join("vary.yaml"),
            "schemas:\n  VarY:\n    fields:\n      nav14/Inner[2] arr:\n      string s:\n",
        )
        .unwrap();
        const INNER_BYTES: u32 = 536_870_907 * 8; // 4_294_967_256 — 7 under u32::MAX − 32

        let sizes = build_workspace_schema_wire_sizes(tmp.path());
        for name in ["nav14/Huge", "nav14/Outer", "nav14/VarOuter", "VarY"] {
            assert_eq!(
                sizes.get(name),
                None,
                "'{name}': an unrepresentable fixed section is OMITTED, never \
                 saturated to u32::MAX or truncated; got {sizes:?}"
            );
        }
        assert_eq!(
            sizes.get("nav14/Inner").copied(),
            Some(INNER_BYTES),
            "a fixed section UNDER the ceiling serves its exact size; got {sizes:?}"
        );
        assert_eq!(
            sizes.get("nav14/Goal").copied(),
            Some(8),
            "the sane sibling still sizes"
        );
        assert_eq!(sizes.get("other14/VarOuter").copied(), Some(4));
        // PREMISE + the ambiguity rule: bare `VarOuter` has two parsed bearers,
        // port resolution refuses it, the fold serves no alias.
        assert!(
            crate::schema_cmd::resolve_port_schema(&tmp.path().join("schemas"), "VarOuter")
                .is_err(),
            "bare `VarOuter` is ambiguous at port resolution"
        );
        assert_eq!(
            sizes.get("VarOuter"),
            None,
            "no alias for a bare name port resolution refuses; got {sizes:?}"
        );

        // `schema info`'s disposition of the SAME files — the surfaces agree.
        let schemas_dir = tmp.path().join("schemas");
        // Store definitions the preflight rejected are REFUSED outright
        // (never a hash of the raw declaration).
        for name in ["nav14/Huge", "nav14/Outer", "nav14/VarOuter"] {
            let err = crate::schema_cmd::schema_info_unified(&schemas_dir, name)
                .expect_err("a rejected store definition is refused");
            assert!(
                err.to_string().contains("resolution preflight rejected"),
                "'{name}': schema info must REFUSE the rejected definition, exactly as \
                 the fold omits it; got: {err}"
            );
        }
        // The YAML entry keeps its documented parse-time provenance with the
        // resolved layout marked UNRESOLVED (its parse-time hash is a real
        // single-entry value; the store has no such value to fall back to).
        let vary = crate::schema_cmd::schema_info_unified(&schemas_dir, "VarY").unwrap();
        assert!(
            !vary.result.entries[0].wire_fixed_size_resolved,
            "'VarY': schema info must reject the composed layout (unresolved fallback)"
        );
        let inner = crate::schema_cmd::schema_info_unified(&schemas_dir, "nav14/Inner").unwrap();
        assert!(inner.result.entries[0].wire_fixed_size_resolved);
        assert_eq!(
            inner.result.entries[0].wire_fixed_size, INNER_BYTES as usize,
            "schema info serves the same exact size for the representable member"
        );
    }

    // The `graph run` live path propagates
    // `TransportError::ExternalNodesInertAtLaunch` (from `run_live`) via
    // `?` → `CliError::Transport`. Pin the CLI-surfaced message: it names each
    // offending node WITH its reason, explains WHY, and states the FIX — so
    // `cerulion graph run` exits non-zero with a clear, actionable message (no
    // panic/backtrace). String seam only (the full live refusal is pinned e2e in
    // `external_gating_replay_iox2_test.rs`).
    #[test]
    fn external_inert_refusal_surfaces_through_cli_error() {
        let te = cerulion_core::TransportError::ExternalNodesInertAtLaunch {
            graph: "perception".to_string(),
            // Three DISTINCT reasons prove the per-offender `node (reason)` render
            // reaches the CLI surface (not just a bare node list) — incl. the
            // FdAboveSelectLimit whose remedy is NOT a self-source.
            nodes: vec![
                ("camera".to_string(), cerulion_core::InertReason::HostDriven),
                ("imu".to_string(), cerulion_core::InertReason::InvalidFd),
                (
                    "radar".to_string(),
                    cerulion_core::InertReason::FdAboveSelectLimit,
                ),
            ],
        };
        // The exact conversion `graph_run`'s `?` performs.
        let cli: CliError = te.into();
        let msg = cli.to_string();
        // Each offender renders as `node (reason)` — the exact pair kills the
        // "cam"-vs-"camera" substring false-positive AND proves distinct reasons
        // render through the CLI surface.
        assert!(
            msg.contains("camera (host-driven)") && msg.contains("imu (invalid fd)"),
            "the CLI error must name every offender WITH its reason; got: {msg}"
        );
        assert!(
            msg.contains("perception"),
            "the CLI error must name the graph; got: {msg}"
        );
        assert!(
            msg.contains("trigger_external"),
            "the CLI error must explain WHY the node can never fire; got: {msg}"
        );
        assert!(
            msg.contains("ExternalSource::Fd") && msg.contains("step()"),
            "the CLI error must state the FIX (a real source, or the polled step() seam); got: {msg}"
        );
        // The FdAboveSelectLimit offender renders WITH its reason, and
        // BOTH of its workaround clauses survive the CLI surface (enable the park /
        // shrink the graph — distinct from the self-source fix, since the fd is
        // fine and only the select watch mechanism has the ceiling).
        assert!(
            msg.contains("radar (fd above select limit)"),
            "the CLI error must name the FdAboveSelectLimit offender WITH its reason; got: {msg}"
        );
        assert!(
            msg.contains("enable the monitor-wait park") && msg.contains("shrink the graph"),
            "both FdAboveSelectLimit workarounds must survive the CLI surface; got: {msg}"
        );
    }

    // The error-building seam for the VIRTUAL time-source refusal. No
    // live run needed — pins the exact contract the `TimeSource::Virtual` arm
    // relies on (an empty external set is NOT refused; a non-empty one produces
    // the aggregated inert-at-launch error, every offender tagged `virtual time`).
    #[test]
    fn virtual_external_inert_refusal_names_nodes_or_is_none() {
        // Empty external set → NO refusal (the zero-cost common path every
        // non-external graph takes).
        assert!(
            virtual_external_inert_refusal("g", &[]).is_none(),
            "a graph with no external nodes must not be refused under virtual time"
        );
        // Non-empty → the aggregated ExternalNodesInertAtLaunch error naming
        // EVERY offender (reason `virtual time`), the graph, and the remedy.
        let ids: Vec<Arc<str>> = vec![Arc::from("camera"), Arc::from("imu")];
        let err = virtual_external_inert_refusal("percep", &ids)
            .expect("external-policy nodes must produce a virtual-time refusal");
        assert!(
            matches!(
                err,
                cerulion_core::TransportError::ExternalNodesInertAtLaunch { .. }
            ),
            "the refusal must be the aggregated inert-at-launch error"
        );
        let msg = err.to_string();
        assert!(
            msg.contains("camera (virtual time)") && msg.contains("imu (virtual time)"),
            "the refusal must name every offender WITH the virtual-time reason; got: {msg}"
        );
        assert!(
            msg.contains("percep"),
            "the refusal must name the graph; got: {msg}"
        );
        assert!(
            msg.contains("--time-source real") && msg.contains("step()"),
            "the refusal must state the remedy (real time / polled step() seam); got: {msg}"
        );
    }

    /// Real wiring: drive `refuse_if_virtual_external_inert`
    /// against a REAL built `GraphRuntime` — not the hand-fed
    /// `virtual_external_inert_refusal` helper — so the actual
    /// `runtime.external_policy_node_ids()` query, the refusal, the
    /// `CliError::Transport` conversion, and the structured log are all
    /// exercised. An EXTERNAL node must be refused BEFORE any stepping; a
    /// non-external node must pass (`Ok`). `#[traced_test]` also pins that the
    /// refusal reaches the structured pipeline. Uses `build_for_test` (isolated
    /// per-test iceoryx2 SHM root).
    ///
    /// The one link this cannot drive cheaply is the literal
    /// `refuse_if_virtual_external_inert(graph_name, &runtime)?;` CALL inside
    /// `graph_run`'s `TimeSource::Virtual` arm — that needs a full workspace + a
    /// built cdylib (`graph_run` loads node entries from disk). That is left to
    /// the e2e/manual path; this closes the refusal-logic + query-wiring gap.
    #[test]
    #[tracing_test::traced_test]
    fn virtual_arm_refuses_a_real_external_runtime_before_stepping() {
        use cerulion_core::graph::node::{ClosureNodeEntry, NodeEntry, NodeInfo};
        use cerulion_core::MacroPolicy;
        use indexmap::IndexMap;

        // --- External node → refused before stepping. ---
        let ext_config = GraphConfig {
            level_assignments: None,
            network: None,
            process_groups: Default::default(),
            process_group_order: Default::default(),
            multi_publisher_topics: Vec::new(),
            name: None,
            identity: "vext".to_string(),
            prefix: "vext_test".to_string(),
            nodes: vec![NodeDef {
                ros2: None,
                id: "driver".to_string(),
                node_type: "driver".to_string(),
                inputs: vec![],
                outputs: vec![OutputDef {
                    name: "out".to_string(),
                    schema: "u8".to_string(),
                    max_slice_len: None,
                    history_size: 0,
                    topic: None,
                }],
            }],
        };
        let ext_entry: Box<dyn NodeEntry> = Box::new(
            ClosureNodeEntry::new(
                NodeInfo::from_names(vec![], vec!["out".to_string()])
                    .with_policy(MacroPolicy::External),
                |_ctx| Ok(()),
            )
            .with_label("vext_driver"),
        );
        let mut ext_factories: IndexMap<String, Box<dyn NodeEntry>> = IndexMap::new();
        ext_factories.insert("driver".to_string(), ext_entry);
        let clock = Arc::new(cerulion_core::VirtualClock::new());
        let ext_runtime =
            cerulion_core::GraphRuntime::build_for_test(ext_config, ext_factories, clock, 4)
                .expect("build external-node runtime");

        // REAL wiring: query the runtime's external ids + refuse.
        let err = refuse_if_virtual_external_inert("vext", &ext_runtime)
            .expect_err("a virtual-time run with an external node must be REFUSED before stepping");
        match err {
            CliError::Transport(cerulion_core::TransportError::ExternalNodesInertAtLaunch {
                ref graph,
                ref nodes,
            }) => {
                assert_eq!(graph, "vext", "the refusal names the graph");
                assert_eq!(
                    nodes.as_slice(),
                    [(
                        "driver".to_string(),
                        cerulion_core::InertReason::VirtualTime
                    )],
                    "the real runtime's external node is named with reason VirtualTime; got {nodes:?}"
                );
            }
            other => {
                panic!("expected CliError::Transport(ExternalNodesInertAtLaunch), got {other:?}")
            }
        }
        // The refusal reached the structured log pipeline.
        assert!(
            logs_contain("provably inert"),
            "the virtual-time refusal must emit a structured tracing::error!"
        );

        // --- Non-external (Period) node → NO refusal (Ok, run proceeds). ---
        let ok_config = GraphConfig {
            level_assignments: None,
            network: None,
            process_groups: Default::default(),
            process_group_order: Default::default(),
            multi_publisher_topics: Vec::new(),
            name: None,
            identity: "vok".to_string(),
            prefix: "vok_test".to_string(),
            nodes: vec![NodeDef {
                ros2: None,
                id: "ticker".to_string(),
                node_type: "ticker".to_string(),
                inputs: vec![],
                outputs: vec![OutputDef {
                    name: "out".to_string(),
                    schema: "u8".to_string(),
                    max_slice_len: None,
                    history_size: 0,
                    topic: None,
                }],
            }],
        };
        let ok_entry: Box<dyn NodeEntry> = Box::new(
            ClosureNodeEntry::new(
                NodeInfo::from_names(vec![], vec!["out".to_string()])
                    .with_policy(MacroPolicy::Period { period_ms: 10 }),
                |_ctx| Ok(()),
            )
            .with_label("vok_ticker"),
        );
        let mut ok_factories: IndexMap<String, Box<dyn NodeEntry>> = IndexMap::new();
        ok_factories.insert("ticker".to_string(), ok_entry);
        let clock2 = Arc::new(cerulion_core::VirtualClock::new());
        let ok_runtime =
            cerulion_core::GraphRuntime::build_for_test(ok_config, ok_factories, clock2, 4)
                .expect("build non-external runtime");
        refuse_if_virtual_external_inert("vok", &ok_runtime)
            .expect("a graph with no external nodes must NOT be refused under virtual time");
    }

    #[test]
    fn test_graph_create() {
        let (_tmp, graphs_dir) = setup_workspace();
        graph_create(&graphs_dir, "perception", Some("robot1")).unwrap();

        let path = graphs_dir.join("perception.yaml");
        assert!(path.exists());

        let content = std::fs::read_to_string(path).unwrap();
        // The file is the name, so the graph's own name
        // appears NOWHERE in its bytes — only the prefix does. Pinned as an
        // ABSENCE beside the presence, because "the file mentions perception"
        // would be satisfied by a `name:` line, which a created graph must not carry.
        assert!(
            !content.contains("perception"),
            "a created graph names itself by its FILE, got:\n{content}"
        );
        assert!(content.contains("robot1"));
    }

    /// `graph create` without `-n`
    /// STAMPS the hostname as the default prefix AT CREATE TIME — frozen in the
    /// YAML so topic names stay deterministic across machines (replay/bags —
    /// runtime prefix resolution is forbidden). An explicit `-n` still wins.
    #[test]
    fn test_graph_create_stamps_hostname_prefix_at_create_time() {
        let (_tmp, graphs_dir) = setup_workspace();
        graph_create(&graphs_dir, "perception", None).unwrap();

        let content = std::fs::read_to_string(graphs_dir.join("perception.yaml")).unwrap();
        assert!(
            content.contains("prefix:"),
            "a default-prefix graph carries a FROZEN `prefix:` line, got:\n{}",
            content
        );

        // graph_read (raw parser, faithful round-trip) returns the FROZEN
        // hostname prefix authored on disk — NOT empty.
        let raw = graph_read(&graphs_dir, "perception").unwrap();
        assert!(
            !raw.prefix.is_empty(),
            "the create-time prefix must be frozen"
        );
        assert_eq!(
            raw.prefix,
            cerulion_core::graph::default_prefix("perception"),
            "the frozen prefix is the machine hostname (the create-time default)"
        );
        assert!(
            !raw.prefix.ends_with(".local"),
            "the frozen default prefix must not include the `.local` suffix: {}",
            raw.prefix
        );

        // An explicit `-n` still wins (unchanged).
        graph_create(&graphs_dir, "navigation", Some("robot1")).unwrap();
        assert_eq!(
            graph_read(&graphs_dir, "navigation").unwrap().prefix,
            "robot1"
        );
    }

    #[test]
    fn test_build_node_def_carries_only_topology() {
        // build_node_def emits topology only (id,
        // type, inputs, outputs). Trigger policy is never written
        // into the YAML — it lives only on the macro side, mutated
        // by `cerulion node modify --trigger`/`--no-trigger`.
        let def = build_node_def(
            "camera",
            Some("front_cam"),
            &[("image".to_string(), Some("sensor_msgs/Image".to_string()))],
            &[],
        );
        assert_eq!(def.id, "front_cam");
        assert_eq!(def.node_type, "camera");
        assert_eq!(def.outputs.len(), 1);
        assert_eq!(def.outputs[0].name, "image");
        assert!(def.inputs.is_empty());
    }

