    /// The round trip goes through the one
    /// write path there is — `node_stage`'s surgical append. The
    /// property: a written graph re-reads to the same identity
    /// and prefix. There is no whole-file
    /// re-serializer to round-trip through.
    #[test]
    fn test_graph_read_write_roundtrip() {
        let (_tmp, graphs_dir) = setup_workspace();
        graph_create(&graphs_dir, "test", Some("prefix")).unwrap();

        let config = graph_read(&graphs_dir, "test").unwrap();
        assert_eq!(config.identity(), "test");
        assert_eq!(config.prefix, "prefix");

        let def = build_node_def(
            "camera",
            None,
            &[("image".to_string(), Some("sensor_msgs/Image".to_string()))],
            &[],
        );
        node_stage(&graphs_dir, "test", def).unwrap();

        let config2 = graph_read(&graphs_dir, "test").unwrap();
        assert_eq!(config2.identity(), config.identity());
        assert_eq!(config2.prefix, config.prefix);
        assert_eq!(config2.nodes.len(), 1);
    }

    // ── The file stem is the graph name ──────────────────────────────────

    /// `graph create` writes NO `name:` line, and a re-read still resolves.
    ///
    /// Asserted on the BYTES, not on the parsed struct: `name` is
    /// `skip_serializing_if = "Option::is_none"`, so a `Some` that happened to
    /// equal the stem would round-trip through the struct invisibly while
    /// putting the key back into every file the tool writes.
    #[test]
    fn graph_create_writes_no_name_key() {
        let (_tmp, graphs_dir) = setup_workspace();
        graph_create(&graphs_dir, "perception", Some("robot")).unwrap();

        let raw = std::fs::read_to_string(graphs_dir.join("perception.yaml")).unwrap();
        assert!(
            !raw.contains("name:"),
            "project rule: a created graph carries no `name:` key, got:\n{raw}"
        );
        assert!(raw.contains("prefix: robot"), "the prefix still writes");

        let config = graph_read(&graphs_dir, "perception").unwrap();
        assert_eq!(config.identity(), "perception");
        assert!(config.name.is_none());
    }

    /// A DIVERGENT legacy `name:` is ignored by every identity surface the
    /// engine mints, and the three are asserted as LITERAL strings rather than
    /// through the same accessor they are derived from.
    ///
    /// The fixture is the shape the rule exists for: a graph renamed on disk
    /// whose `name:` line was never updated. Before it, the bag stemmed and
    /// the rings tagged under `legacy_internal_name`.
    #[test]
    fn a_divergent_declared_name_stems_nothing() {
        let (_tmp, graphs_dir) = setup_workspace();
        std::fs::write(
            graphs_dir.join("renamed.yaml"),
            "name: legacy_internal_name\nprefix: robot\nnodes: []\n",
        )
        .unwrap();

        let config = graph_read(&graphs_dir, "renamed").unwrap();
        assert_eq!(config.identity(), "renamed");

        // (2) the BAG filename stem.
        let paths = resolve_recording_paths(
            std::path::Path::new("/tmp/rec"),
            config.identity(),
            std::time::Duration::from_secs(1_700_000_000),
        );
        let bag = paths
            .out
            .file_name()
            .unwrap()
            .to_string_lossy()
            .into_owned();
        assert!(
            bag.starts_with("renamed_"),
            "the bag is stemmed by the FILE, got `{bag}`"
        );
        assert!(!bag.contains("legacy_internal_name"), "got `{bag}`");

        // (3) the TRACE-RING tags (worker + departure), which a recorder opens
        // by name — a stem/tag disagreement is an un-openable ring.
        assert_eq!(
            worker_recording_ring_tag(config.identity(), 4242, 0),
            worker_recording_ring_tag("renamed", 4242, 0)
        );
        assert!(
            !worker_recording_ring_tag(config.identity(), 4242, 0).contains("legacy_internal_name")
        );
        assert!(!departure_ring_tag(config.identity(), 4242).contains("legacy_internal_name"));

        // BACK-COMPAT: the key itself survives a rewrite. The write goes
        // through `node_stage`,
        // the one write path there is — and the claim is STRONG there:
        // the surgical splice touches only the `nodes:` block, so `name:`
        // survives because nothing rewrote it, rather than because a
        // re-serializer happened to round-trip it.
        let def = build_node_def(
            "camera",
            None,
            &[("image".to_string(), Some("sensor_msgs/Image".to_string()))],
            &[],
        );
        node_stage(&graphs_dir, "renamed", def).unwrap();
        let raw = std::fs::read_to_string(graphs_dir.join("renamed.yaml")).unwrap();
        assert!(
            raw.contains("name: legacy_internal_name"),
            "the deprecated key must round-trip, got:\n{raw}"
        );
    }

    /// The EFFECTIVE-config embed never FABRICATES a `name:`.
    ///
    /// A bag's `graph.yaml` is machine-read, so a key invented at render time
    /// would be a claim about the graph nobody wrote — while a key the author
    /// DID write must survive, because that is what an older bag (written while
    /// `name:` was still emitted) looks like and replay still parses it.
    #[test]
    fn the_effective_embed_fabricates_no_name() {
        let (_tmp, graphs_dir) = setup_workspace();
        graph_create(&graphs_dir, "embedme", None).unwrap();
        let fresh = graph_read(&graphs_dir, "embedme").unwrap();
        let rendered = render_effective_graph_yaml(&fresh).expect("render");
        assert!(
            !rendered.contains("name:"),
            "a nameless graph must embed no `name:`, got:\n{rendered}"
        );

        std::fs::write(
            graphs_dir.join("legacy.yaml"),
            "name: older\nprefix: p\nnodes: []\n",
        )
        .unwrap();
        let legacy = graph_read(&graphs_dir, "legacy").unwrap();
        let rendered = render_effective_graph_yaml(&legacy).expect("render");
        assert!(
            rendered.contains("name: older"),
            "an authored key must survive into the embed, got:\n{rendered}"
        );
    }

