    // ─── find_cdylib profile preference ──────────────────

    /// Write an empty placeholder cdylib file at
    /// `<ws_root>/target/<profile>/<libname>` so `find_cdylib`'s
    /// existence check (it never loads the library) resolves it.
    /// This is the DEFAULT (`CARGO_TARGET_DIR`-unset) location — the
    /// `CARGO_TARGET_DIR` tests below write to a custom base via
    /// [`touch_cdylib_at`].
    fn touch_cdylib(ws_root: &Path, node_type: &str, profile: &str) -> std::path::PathBuf {
        touch_cdylib_at(&ws_root.join("target"), node_type, profile)
    }

    /// Write an empty placeholder cdylib at
    /// `<base>/<profile>/<libname>` (the base cargo writes into) so
    /// `find_cdylib`'s existence check resolves it. Lets the
    /// `CARGO_TARGET_DIR` tests place artifacts at an arbitrary base.
    fn touch_cdylib_at(base: &Path, node_type: &str, profile: &str) -> std::path::PathBuf {
        let dir = base.join(profile);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join(cdylib_name(node_type));
        std::fs::write(&path, b"").unwrap();
        path
    }

    #[test]
    fn test_find_cdylib_default_picks_freshest_debug() {
        // Default mode (prefer_release == false) auto-selects
        // the freshest build. With a NEWER debug and an older release,
        // debug must win even though release exists.
        // This test resolves the DEFAULT base (<ws>/target) → must hold
        // the env lock and guarantee CARGO_TARGET_DIR is unset, or a
        // parallel env-mutating test below can redirect the base mid-flight.
        let _env = unset_target_dir_for_test();
        let tmp = tempfile::tempdir().unwrap();
        let debug = touch_cdylib(tmp.path(), "camera", "debug");
        let release = touch_cdylib(tmp.path(), "camera", "release");
        set_mtime(&release, 1_000);
        set_mtime(&debug, 2_000);

        let found = find_cdylib(tmp.path(), "camera", false).unwrap();
        assert_eq!(found.path, debug);
        assert_eq!(found.profile(), "debug");
        assert!(!found.release);
    }

    #[test]
    fn test_find_cdylib_default_picks_freshest_release() {
        // The freshest-wins symmetry — a NEWER release beats
        // an older debug in default mode (the case
        // where a fixed debug-first order would pick a stale debug
        // build over a freshly-rebuilt release one).
        // This test resolves the DEFAULT base, so hold the env lock +
        // unset CARGO_TARGET_DIR so a parallel env-mutating test can't
        // redirect the base mid-flight.
        let _env = unset_target_dir_for_test();
        let tmp = tempfile::tempdir().unwrap();
        let debug = touch_cdylib(tmp.path(), "camera", "debug");
        let release = touch_cdylib(tmp.path(), "camera", "release");
        set_mtime(&debug, 1_000);
        set_mtime(&release, 2_000);

        let found = find_cdylib(tmp.path(), "camera", false).unwrap();
        assert_eq!(found.path, release);
        assert_eq!(found.profile(), "release");
        assert!(found.release);
    }

