    #[test]
    fn test_find_cdylib_absolute_target_dir_moves_base() {
        let _lock = cargo_target_dir_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let tmp = tempfile::tempdir().unwrap();
        let custom = tmp.path().join("custom");
        let _guard = CargoTargetDirGuard::set(&custom);

        // Base resolves verbatim to the absolute custom dir.
        assert_eq!(cdylib_target_base(tmp.path()), custom);

        // A cdylib at the custom base IS found...
        let debug = touch_cdylib_at(&custom, "camera", "debug");
        let release = touch_cdylib_at(&custom, "camera", "release");
        // The default (prefer_release == false) is freshest-by-mtime,
        // so pin debug newer to make it deterministically the default winner
        // (this test proves the BASE moved, not the profile tie-break).
        set_mtime(&release, 1_000);
        set_mtime(&debug, 2_000);
        let found = find_cdylib(tmp.path(), "camera", true).unwrap();
        assert_eq!(found.path, release); // forced release-first (mtime-independent)
        let found = find_cdylib(tmp.path(), "camera", false).unwrap();
        assert_eq!(found.path, debug); // freshest: debug is newer

        // ...and one at the un-overridden <ws_root>/target/... is NOT (proves the
        // base actually moved — not merely that both happen to exist).
        let tmp2 = tempfile::tempdir().unwrap();
        let custom2 = tmp2.path().join("elsewhere");
        let _guard2 = CargoTargetDirGuard::set(&custom2);
        touch_cdylib(tmp2.path(), "camera", "debug"); // writes <ws>/target, NOT custom2
        let err = find_cdylib(tmp2.path(), "camera", false).unwrap_err();
        let msg = err.to_string();
        assert!(
            msg.contains(&custom2.join("debug").display().to_string()),
            "error must name the redirected base, not <ws>/target; got: {msg}"
        );
    }

    #[test]
    fn test_find_cdylib_relative_target_dir_resolves_under_ws_root() {
        // A RELATIVE CARGO_TARGET_DIR resolves relative to workspace_root
        // (cargo anchors a relative target-dir at its cwd, and node_build's
        // cargo runs with cwd = workspace_root — they MUST agree).
        let _lock = cargo_target_dir_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let tmp = tempfile::tempdir().unwrap();
        let _guard = CargoTargetDirGuard::set(Path::new("custom_target"));

        let base = tmp.path().join("custom_target");
        assert_eq!(cdylib_target_base(tmp.path()), base);

        let release = touch_cdylib_at(&base, "camera", "release");
        let found = find_cdylib(tmp.path(), "camera", true).unwrap();
        assert_eq!(found.path, release);
        assert_eq!(
            found.path,
            tmp.path()
                .join("custom_target/release")
                .join(cdylib_name("camera"))
        );

        // The un-overridden <ws_root>/target/... location must NOT resolve.
        let tmp2 = tempfile::tempdir().unwrap();
        let _guard2 = CargoTargetDirGuard::set(Path::new("custom_target"));
        touch_cdylib(tmp2.path(), "camera", "release"); // <ws>/target, not custom_target
        assert!(
            find_cdylib(tmp2.path(), "camera", true).is_err(),
            "a cdylib under <ws>/target must NOT resolve when CARGO_TARGET_DIR=custom_target"
        );
    }

