    // ─── stale-cdylib detection ──────────────────────────

    /// Set an explicit mtime (`UNIX_EPOCH + secs`) on an existing
    /// file. Uses `std::fs::File::set_modified` (stable since Rust
    /// 1.75) so no `filetime` dependency is needed.
    fn set_mtime(path: &Path, secs_after_epoch: u64) {
        let t = std::time::SystemTime::UNIX_EPOCH + Duration::from_secs(secs_after_epoch);
        std::fs::File::options()
            .write(true)
            .open(path)
            .unwrap()
            .set_modified(t)
            .unwrap();
    }

    /// Write a file (creating parent dirs) and pin its mtime.
    fn write_with_mtime(path: &Path, secs_after_epoch: u64) {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, b"x").unwrap();
        set_mtime(path, secs_after_epoch);
    }

    fn epoch_plus(secs: u64) -> std::time::SystemTime {
        std::time::SystemTime::UNIX_EPOCH + Duration::from_secs(secs)
    }

    #[test]
    fn test_newest_mtime_missing_dir_returns_none() {
        let tmp = tempfile::tempdir().unwrap();
        assert_eq!(
            newest_mtime_in_dir(&tmp.path().join("does_not_exist")),
            None
        );
    }

    #[test]
    fn test_newest_mtime_empty_dir_returns_none() {
        let tmp = tempfile::tempdir().unwrap();
        assert_eq!(newest_mtime_in_dir(tmp.path()), None);
    }

    #[test]
    fn test_newest_mtime_single_file() {
        let tmp = tempfile::tempdir().unwrap();
        write_with_mtime(&tmp.path().join("a.rs"), 1_000);
        assert_eq!(newest_mtime_in_dir(tmp.path()), Some(epoch_plus(1_000)));
    }

    #[test]
