    #[test]
    fn test_build_input_mtime_ignores_non_build_inputs() {
        // The staleness scan covers build inputs only (Cargo.toml,
        // build.rs, src/**): nested build output (`target/`), VCS
        // metadata (`.git/`), and checked-in datasets must neither
        // produce false stale warnings nor slow the scan.
        let tmp = tempfile::tempdir().unwrap();
        write_with_mtime(&tmp.path().join("src").join("lib.rs"), 1_000);
        write_with_mtime(&tmp.path().join("target").join("artifact.so"), 9_000);
        write_with_mtime(
            &tmp.path().join("target").join("debug").join("deep.so"),
            9_500,
        );
        write_with_mtime(&tmp.path().join(".git").join("index"), 9_800);
        write_with_mtime(&tmp.path().join("data").join("weights.onnx"), 9_900);
        assert_eq!(
            newest_build_input_mtime(tmp.path()),
            Some(epoch_plus(1_000)),
            "only build inputs may contribute to the staleness scan"
        );
    }

