    #[test]
    fn test_build_input_mtime_includes_benches_examples_tests() {
        // Cargo recompiles when `benches/`, `examples/`, or `tests/`
        // change — they are build inputs too. A bench file newer than
        // anything in `src/` must drive the staleness verdict, else a
        // node with only its bench touched would falsely read fresh.
        let tmp = tempfile::tempdir().unwrap();
        write_with_mtime(&tmp.path().join("src").join("lib.rs"), 1_000);
        write_with_mtime(&tmp.path().join("benches").join("bench.rs"), 4_000);
        write_with_mtime(&tmp.path().join("examples").join("demo.rs"), 3_000);
        write_with_mtime(&tmp.path().join("tests").join("it.rs"), 2_000);
        assert_eq!(
            newest_build_input_mtime(tmp.path()),
            Some(epoch_plus(4_000)),
            "benches/examples/tests are build inputs and must contribute"
        );
    }

    #[cfg(unix)]
    #[test]
    fn test_newest_mtime_follows_symlinked_files() {
        // Shared sources symlinked into src/ are build inputs; the
        // walk must follow file symlinks (and a fully symlinked walk
        // root resolves via read_dir).
        let tmp = tempfile::tempdir().unwrap();
        let shared = tmp.path().join("shared.rs");
        write_with_mtime(&shared, 7_000);
        let src = tmp.path().join("src");
        std::fs::create_dir_all(&src).unwrap();
        write_with_mtime(&src.join("lib.rs"), 1_000);
        std::os::unix::fs::symlink(&shared, src.join("common.rs")).unwrap();
        assert_eq!(
            newest_mtime_in_dir(&src),
            Some(epoch_plus(7_000)),
            "symlinked source files must count as build inputs"
        );
    }

    #[cfg(unix)]
    #[test]
    fn test_newest_mtime_skips_symlinked_dirs_without_hanging() {
        // A symlink cycle (dir linking back to an ancestor) must not
        // hang the walk; symlinked directories are skipped.
        let tmp = tempfile::tempdir().unwrap();
        let src = tmp.path().join("src");
        std::fs::create_dir_all(&src).unwrap();
        write_with_mtime(&src.join("lib.rs"), 1_000);
        std::os::unix::fs::symlink(tmp.path(), src.join("loop")).unwrap();
        assert_eq!(
            newest_mtime_in_dir(&src),
            Some(epoch_plus(1_000)),
            "symlinked dirs are skipped (cycle safety), files still counted"
        );
    }

