    #[test]
    #[tracing_test::traced_test]
    fn test_find_cdylib_detects_stale_build_silently() {
        let _env = unset_target_dir_for_test();
        // The lookup computes staleness but does NOT log — the load
        // path (`warn_if_stale`) and the validate report own the
        // user-facing surfaces, so one condition never produces
        // duplicate warnings.
        let tmp = tempfile::tempdir().unwrap();
        write_with_mtime(
            &tmp.path()
                .join("nodes")
                .join("camera")
                .join("src")
                .join("lib.rs"),
            2_000,
        );
        let lib = touch_cdylib(tmp.path(), "camera", "debug");
        set_mtime(&lib, 1_000);

        let found = find_cdylib(tmp.path(), "camera", false).unwrap();
        assert_eq!(
            found.path, lib,
            "staleness must not change the resolved path"
        );
        assert!(found.stale, "stale build must be detected");
        assert!(
            !logs_contain("node source is newer"),
            "find_cdylib itself must stay silent — callers own the warning"
        );
    }

