    /// Build a `GraphConfig` with `n` instances all of node type
    /// `node_type` (ids `<type>_0..n`), no ports.
    fn config_with_n_instances(node_type: &str, n: usize) -> GraphConfig {
        GraphConfig {
            level_assignments: None,
            network: None,
            process_groups: Default::default(),
            process_group_order: Default::default(),
            name: None,
            identity: "test".to_string(),
            prefix: "p".to_string(),
            nodes: (0..n)
                .map(|i| NodeDef {
                    ros2: None,
                    id: format!("{}_{}", node_type, i),
                    node_type: node_type.to_string(),
                    inputs: vec![],
                    outputs: vec![],
                })
                .collect(),
            // A later merge added this field to GraphConfig.
            multi_publisher_topics: vec![],
        }
    }

    #[test]
    fn test_resolve_cdylib_cache_dedups_per_type() {
        let _env = unset_target_dir_for_test();
        // The shared resolution helper that both graph_validate and
        // graph_run consume must memoize per node *type*: K instances
        // of one type yield exactly one cache entry (one staleness
        // walk), not K.
        let tmp = tempfile::tempdir().unwrap();
        touch_cdylib(tmp.path(), "camera", "debug");
        let config = config_with_n_instances("camera", 3);

        let cache = resolve_cdylib_cache(tmp.path(), &config, false);
        assert_eq!(
            cache.len(),
            1,
            "three instances of one type must produce one cache entry"
        );
        assert!(cache.get("camera").unwrap().is_ok());
    }

    #[test]
    #[tracing_test::traced_test]
    fn test_resolve_cdylib_cache_flags_stale_then_warns() {
        let _env = unset_target_dir_for_test();
        // Mirrors the graph_run load-path contract without iceoryx2:
        // resolve_cdylib_cache flags staleness, and warn_if_stale —
        // the exact call graph_run makes on the resolved entry — emits
        // the rebuild warning. A refactor that drops staleness from the
        // shared cache (the input to graph_run's warn_if_stale) would
        // fail here.
        let tmp = tempfile::tempdir().unwrap();
        let lib = touch_cdylib(tmp.path(), "camera", "debug");
        set_mtime(&lib, 1_000);
        write_with_mtime(
            &tmp.path()
                .join("nodes")
                .join("camera")
                .join("src")
                .join("lib.rs"),
            2_000,
        );
        let config = config_with_n_instances("camera", 2);

        let cache = resolve_cdylib_cache(tmp.path(), &config, false);
        let resolved = cache
            .get("camera")
            .unwrap()
            .as_ref()
            .expect("camera cdylib must resolve");
        assert!(
            resolved.stale,
            "the shared cache must carry the staleness verdict graph_run warns on"
        );

        // Drive the exact warn_if_stale call graph_run makes on the
        // resolved entry and assert the rebuild warning fires.
        warn_if_stale("camera", resolved);
        assert!(
            logs_contain("node source is newer than the built cdylib"),
            "warn_if_stale on the resolved cache entry must emit the rebuild warning"
        );
    }

