    #[test]
    fn test_graph_validate_stale_cdylib_warns_in_detail_but_passes() {
        let _env = unset_target_dir_for_test();
        let (_tmp, ws_root) = setup_workspace_with_camera_node();
        let lib = touch_cdylib(&ws_root, "camera", "debug");
        set_mtime(&lib, 1_000);
        set_mtime(
            &ws_root
                .join("nodes")
                .join("camera")
                .join("src")
                .join("lib.rs"),
            2_000,
        );

        let report = graph_validate(&ws_root, "test", false).unwrap();
        let check = cdylib_check(&report);
        assert!(
            check.passed,
            "staleness is non-fatal — the check must still pass; got: {}",
            check.detail
        );
        let warning = check
            .warning
            .as_deref()
            .expect("stale build must attach a warning to the check");
        assert!(
            warning.contains("node source is newer than this build"),
            "warning must describe the staleness; got: {warning}"
        );
        assert!(
            warning.contains("cerulion node build camera"),
            "warning must advise the rebuild command; got: {warning}"
        );
        assert!(
            check.to_string().contains("WARN:"),
            "rendered check must surface the warning; got: {check}"
        );
        assert!(
            report.has_warnings(),
            "report must expose warned-but-passed state structurally"
        );
    }

