    /// Count the cdylib check entries for a given node type.
    fn count_cdylib_checks(report: &ValidationReport, node_type: &str) -> usize {
        let needle = format!("{CDYLIB_CHECK_PREFIX}{}'", node_type);
        report.checks.iter().filter(|c| c.label == needle).count()
    }

    #[test]
    fn test_graph_validate_multi_instance_one_cdylib_check_per_type() {
        let _env = unset_target_dir_for_test();
        // Three instances of one node type must produce EXACTLY ONE
        // `cdylib '<type>'` report entry, not three identical ones —
        // the resolution is memoized per type, and so is the report
        // line (otherwise a stale build triples its warning and
        // inflates the pass/total counts).
        let (_tmp, graphs_dir) = setup_workspace();
        graph_create(&graphs_dir, "test", Some("p")).unwrap();
        for id in ["camera_left", "camera_right", "camera_top"] {
            let def = build_node_def(
                "camera",
                Some(id),
                &[("image".to_string(), Some("sensor_msgs/Image".to_string()))],
                &[],
            );
            node_stage(&graphs_dir, "test", def).unwrap();
        }

        let ws_root = graphs_dir.parent().unwrap().to_path_buf();
        let src_dir = ws_root.join("nodes").join("camera").join("src");
        std::fs::create_dir_all(&src_dir).unwrap();
        std::fs::write(
            src_dir.join("lib.rs"),
            r#"use cerulion_core::prelude::*;
#[cerulion_node(period_ms = 100)]
#[derive(Default)]
struct CameraNode { tick_count: u32 }
"#,
        )
        .unwrap();
        touch_cdylib(&ws_root, "camera", "debug");

        let report = graph_validate(&ws_root, "test", false).unwrap();
        assert_eq!(
            count_cdylib_checks(&report, "camera"),
            1,
            "three instances of one type must yield exactly one cdylib check; \
             got {} — report:\n{}",
            count_cdylib_checks(&report, "camera"),
            report
        );
    }

    #[test]
    fn test_graph_validate_multi_instance_stale_warns_once() {
        let _env = unset_target_dir_for_test();
        // Same as above but with a stale build: the single cdylib
        // check must carry the warning, and the report must report
        // exactly one warned check (not three).
        let (_tmp, graphs_dir) = setup_workspace();
        graph_create(&graphs_dir, "test", Some("p")).unwrap();
        for id in ["camera_left", "camera_right"] {
            let def = build_node_def(
                "camera",
                Some(id),
                &[("image".to_string(), Some("sensor_msgs/Image".to_string()))],
                &[],
            );
            node_stage(&graphs_dir, "test", def).unwrap();
        }
        let ws_root = graphs_dir.parent().unwrap().to_path_buf();
        let src_dir = ws_root.join("nodes").join("camera").join("src");
        std::fs::create_dir_all(&src_dir).unwrap();
        std::fs::write(
            src_dir.join("lib.rs"),
            r#"use cerulion_core::prelude::*;
#[cerulion_node(period_ms = 100)]
#[derive(Default)]
struct CameraNode { tick_count: u32 }
"#,
        )
        .unwrap();
        let lib = touch_cdylib(&ws_root, "camera", "debug");
        set_mtime(&lib, 1_000);
        set_mtime(&src_dir.join("lib.rs"), 2_000);

        let report = graph_validate(&ws_root, "test", false).unwrap();
        assert_eq!(
            count_cdylib_checks(&report, "camera"),
            1,
            "two instances of one type must yield exactly one cdylib check"
        );
        let warned = report.checks.iter().filter(|c| c.warning.is_some()).count();
        assert_eq!(
            warned, 1,
            "a single stale type must warn exactly once, not once per instance; report:\n{}",
            report
        );
    }

    #[test]
    fn test_validation_report_summary_surfaces_warning_count() {
        // The Display summary line must surface the warning count when
        // any passed check is warned, so a CI script scanning only the
        // summary line is not blind to stale builds (all_passed() is
        // still true).
        let report = ValidationReport {
            graph_name: "test".to_string(),
            checks: vec![
                ValidationCheck::pass("a", "ok"),
                ValidationCheck::pass_with_warning("b", "ok", "stale"),
                ValidationCheck::pass_with_warning("c", "ok", "stale"),
            ],
        };
        assert!(report.all_passed());
        assert!(report.has_warnings());
        let out = format!("{}", report);
        assert!(
            out.contains("3/3 checks passed, 2 with warnings."),
            "summary must surface the warning count; got:\n{out}"
        );
    }

    #[test]
    fn test_validation_report_summary_no_warning_suffix_when_clean() {
        // No warnings → no warning suffix (avoid a misleading "0 with
        // warnings" tail on a clean report).
        let report = ValidationReport {
            graph_name: "test".to_string(),
            checks: vec![ValidationCheck::pass("a", "ok")],
        };
        let out = format!("{}", report);
        assert!(
            out.contains("1/1 checks passed."),
            "clean summary; got:\n{out}"
        );
        assert!(
            !out.contains("with warnings"),
            "clean report must not mention warnings; got:\n{out}"
        );
    }

