    #[test]
    fn test_graph_validate_data_trigger_self_loop() {
        let _env = unset_target_dir_for_test();
        // Consumer wires its trigger input to its own output —
        // would tick infinitely. The runtime catches it at build
        // time; this pre-run check catches it before
        // the run starts.
        let (_tmp, graphs_dir) = setup_workspace();
        let ws_root = graphs_dir.parent().unwrap();
        graph_create(&graphs_dir, "test", Some("p")).unwrap();

        // Self-loop: consumer's `data` input sourced from
        // `consumer/data` (its own output).
        let cons_def = build_node_def(
            "consumer",
            None,
            &[("data".to_string(), Some("std_msgs/String".to_string()))],
            &[("data".to_string(), "consumer/data".to_string())],
        );
        node_stage(&graphs_dir, "test", cons_def).unwrap();
        // Override consumer source to also declare the `data` output.
        let src_dir = ws_root.join("nodes").join("consumer").join("src");
        std::fs::create_dir_all(&src_dir).unwrap();
        std::fs::write(
            src_dir.join("lib.rs"),
            r#"use cerulion_core::prelude::*;
#[cerulion_node]
#[derive(Default)]
struct ConsumerNode {
    #[input(trigger)]
    data: u32,
    #[output]
    data_out: u32,
    tick_count: u32,
}
"#,
        )
        .unwrap();

        // Override the YAML so the trigger input points at this
        // node's own output. The default `node_stage` writes the
        // exact source we passed, but `output` was stubbed only
        // for trigger purposes; rebuild the binding to point at
        // `consumer/data` explicitly via a fresh write.
        let yaml_path = graphs_dir.join("test.yaml");
        let yaml = std::fs::read_to_string(&yaml_path).unwrap();
        // We need the trigger input's source to be `consumer/data`
        // — already so via build_node_def's `data` → `consumer/data`
        // binding above. The consumer's own output is `data_out`
        // in lib.rs but the YAML output entry was built with name
        // `data`, mismatched on purpose. Rewrite the YAML so the
        // consumer's output is named `data` to trigger the loop
        // detection against the YAML output name (which is what
        // `validate_graph` checks).
        let yaml = yaml.replace("name: data_out", "name: data");
        std::fs::write(&yaml_path, yaml).unwrap();

        let report = graph_validate(ws_root, "test", false).unwrap();
        // Require the binding check entry to be present. Using
        // `if let Some(...)` here would let a future regression
        // that deletes the DataTrigger cross-check block in
        // `graph_validate` silently leave this test green. Match
        // the sibling tests' `.expect(...)` pattern.
        let binding_check = report
            .checks
            .iter()
            .find(|c| c.label.contains("data_trigger binding 'consumer'"))
            .expect("expected a data_trigger binding check entry for the self-loop case");
        assert!(
            !binding_check.passed,
            "self-loop binding must fail; got: {}",
            binding_check.detail
        );
        assert!(
            binding_check.detail.contains("infinite loop")
                || binding_check.detail.contains("own output"),
            "diagnostic must mention the self-loop; got: {}",
            binding_check.detail
        );
    }

    /// Helper: stages a consumer node with TWO `#[input(trigger)]` fields
    /// (`a`, `b`) under `sync_window_ms = 25`. Used by the sync
    /// trigger-binding validate tests below.
    fn write_consumer_with_sync_triggers(ws_root: &Path) {
        let src_dir = ws_root.join("nodes").join("consumer").join("src");
        std::fs::create_dir_all(&src_dir).unwrap();
        std::fs::write(
            src_dir.join("lib.rs"),
            r#"use cerulion_core::prelude::*;

#[cerulion_node(sync_window_ms = 25)]
#[derive(Default)]
struct ConsumerNode {
    #[input(trigger)]
    a: u32,
    #[input(trigger)]
    b: u32,
    tick_count: u32,
}
"#,
        )
        .unwrap();
    }

    #[test]
    fn test_graph_validate_sync_trigger_missing_yaml_input() {
        let _env = unset_target_dir_for_test();
        // The consumer's macro declares TWO
        // `#[input(trigger)]` sync ports but the graph YAML wires only `a`.
        // The runtime's `validate_macro_sync_trigger_wiring` hard-rejects
        // this at `graph run` (the alignment set would silently shrink);
        // `graph validate` must mirror it — without this check validate PASSES the
        // exact graph run refuses (a CLI/engine contract-alignment gap).
        let (_tmp, graphs_dir) = setup_workspace();
        let ws_root = graphs_dir.parent().unwrap();
        graph_create(&graphs_dir, "test", Some("p")).unwrap();

        let prod_def = build_node_def(
            "producer",
            None,
            &[("data".to_string(), Some("std_msgs/String".to_string()))],
            &[],
        );
        node_stage(&graphs_dir, "test", prod_def).unwrap();
        let prod_src = ws_root.join("nodes").join("producer").join("src");
        std::fs::create_dir_all(&prod_src).unwrap();
        std::fs::write(
            prod_src.join("lib.rs"),
            r#"use cerulion_core::prelude::*;
#[cerulion_node(period_ms = 100)]
#[derive(Default)]
struct ProducerNode { #[output] data: u32, tick_count: u32 }
"#,
        )
        .unwrap();

        // Only `a` is wired; the trigger-marked `b` is NOT.
        let cons_def = build_node_def(
            "consumer",
            None,
            &[],
            &[("a".to_string(), "producer/data".to_string())],
        );
        node_stage(&graphs_dir, "test", cons_def).unwrap();
        write_consumer_with_sync_triggers(ws_root);

        let report = graph_validate(ws_root, "test", false).unwrap();
        // The wired `a` port emits a PASS entry; the unwired `b` port must
        // emit the FAIL entry (find specifically the failing one).
        let failing = report
            .checks
            .iter()
            .find(|c| c.label.contains("sync trigger binding 'consumer'") && !c.passed)
            .expect("expected a FAILING sync trigger binding check for the unwired port");
        assert!(
            failing.detail.contains("'b'"),
            "diagnostic must name the unwired trigger field 'b'; got: {}",
            failing.detail
        );
        assert!(
            failing.detail.contains("doesn't wire an input named"),
            "diagnostic must state the cause (mirroring the runtime guard); got: {}",
            failing.detail
        );
        assert!(
            failing
                .detail
                .contains("a `name: b` entry with its `source: <topic>`"),
            "diagnostic must state the YAML fix naming both keys; got: {}",
            failing.detail
        );
    }

